function memberPresence(source){const state=source.presence||'offline';return `<span class="member-presence">${presenceDot(state)}${statusLabel(state)}${state==='offline'&&source.lastOnline?' · Last online '+esc(new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(source.lastOnline))):''}</span>`}
