function controlIcon(name,off){return icon(name).replace('</svg>',(off?'<path d="m3 3 18 18" stroke-width="2.1"/>':'')+'</svg>')}
function mediaControlButtons(){return `<div class="media-controls"><button type="button" id="toggle-mute" aria-label="${mediaControls.muted?'Unmute microphone':'Mute microphone'}" aria-pressed="${mediaControls.muted}" title="${mediaControls.muted?'Unmute':'Mute'}">${controlIcon('mic',mediaControls.muted)}</button><button type="button" id="toggle-deafen" aria-label="${mediaControls.deafened?'Undeafen':'Deafen'}" aria-pressed="${mediaControls.deafened}" title="${mediaControls.deafened?'Undeafen':'Deafen'}">${controlIcon('headphones',mediaControls.deafened)}</button><button type="button" id="toggle-camera" aria-label="${mediaControls.camera?'Turn camera off':'Turn camera on'}" aria-pressed="${mediaControls.camera}" title="${mediaControls.camera?'Turn camera off':'Turn camera on'}">${controlIcon('camera',!mediaControls.camera)}</button><button class="settings-trigger" data-page="Settings" aria-label="Settings" title="Settings">${icon('settings')}</button></div>`}
function applyMediaControls(){document.querySelectorAll('audio').forEach(a=>a.muted=mediaControls.deafened);recording?.stream?.getAudioTracks().forEach(t=>t.enabled=!mediaControls.muted);activeCall?.stream?.getAudioTracks().forEach(t=>t.enabled=!mediaControls.muted);if(mediaControls.muted&&recording){cancelRecording();const panel=document.querySelector('#recording-controls');if(panel)panel.hidden=true;document.querySelector('#record-voice')?.setAttribute('aria-pressed','false')}}
function bindMediaControls(){const update=()=>{document.querySelector('.media-controls').outerHTML=mediaControlButtons();bindMediaControls();document.querySelector('.media-controls [data-page]').onclick=()=>go('Settings');applyMediaControls()};document.querySelector('#toggle-mute').onclick=()=>{mediaControls.muted=!mediaControls.muted;if(!mediaControls.muted)mediaControls.deafened=false;update()};document.querySelector('#toggle-deafen').onclick=()=>{if(!mediaControls.deafened){mediaControls.muteBeforeDeafen=mediaControls.muted;mediaControls.deafened=true;mediaControls.muted=true}else{mediaControls.deafened=false;mediaControls.muted=mediaControls.muteBeforeDeafen}update()};document.querySelector('#toggle-camera').onclick=()=>{mediaControls.camera=!mediaControls.camera;update()}}
