const persist=()=>{if(window.NavRestoring)return;try{localStorage.setItem('daily-mockup',JSON.stringify({storageVersion:1,sources,read,saved,profile,conversations,lastOnline,settings,ownPosts,postDraft,categories,publishingDraft,tags}))}catch{toast('Storage is full. Try a smaller image.')}};
