const emptyView=(p='Saved',source=null)=>({page:p,query:'',kind:'All types',network:'All platforms',searched:false,selectedSource:source,tab:'All updates',sourceMode:'Updates',draft:'',scroll:0,opened:[]});
let workspaceTabs=[{key:'Saved',...emptyView()}],activeKey='Saved',tabGroups=[];
try{const saved=JSON.parse(localStorage.getItem('daily-workspace')||'null');if(saved&&Array.isArray(saved.tabs)&&saved.tabs.length){const seen=new Set();workspaceTabs=saved.tabs.filter(t=>t&&typeof t.key==='string'&&!seen.has(t.key)&&seen.add(t.key)&&['Sources','Source','Search','Saved','Files','Settings','Profile','Today','Read'].includes(t.page)).map(t=>({...emptyView(),...t,color:t.color?TabTree.color(t.color):null}));if(!workspaceTabs.length)workspaceTabs=[{key:'Saved',...emptyView()}];tabGroups=Array.isArray(saved.groups)?saved.groups.filter(g=>g&&typeof g.id==='string'&&typeof g.name==='string').map(g=>({...g,color:TabTree.color(g.color)})):[];for(const g of tabGroups)if(!TabTree.canParent(tabGroups,g.id,g.parentId))g.parentId=null;for(const t of workspaceTabs)if(!tabGroups.some(g=>g.id===t.groupId))t.groupId=null;activeKey=workspaceTabs.some(t=>t.key===saved.activeKey)?saved.activeKey:workspaceTabs[0].key;({page,query,kind,network,searched,selectedSource,tab,sourceMode}=workspaceTabs.find(t=>t.key===activeKey))}}catch{}
function persistWorkspace(){if(window.NavRestoring)return;try{localStorage.setItem('daily-workspace',JSON.stringify({tabs:workspaceTabs,groups:tabGroups,activeKey}))}catch{toast('Could not save tabs')}}
function saveView(){announceTyping(false);cancelRecording();document.querySelector('.emoji-picker')?.remove();const t=workspaceTabs.find(t=>t.key===activeKey);if(!t)return;Object.assign(t,{page,query,kind,network,searched,selectedSource,tab,sourceMode,scroll:document.querySelector('#app').scrollTop,opened:[...document.querySelectorAll('details[open][data-post]')].map(e=>e.dataset.post),liveOpened:window.SourceFeeds?.openIds(document)||[]});const input=document.querySelector('#search-input');if(input)t.draft=input.value;persistWorkspace();}
function activateTab(key){saveView();const t=workspaceTabs.find(t=>t.key===key);if(!t)return;activeKey=key;for(const id of TabTree.ancestors(tabGroups,t.groupId)){const group=tabGroups.find(g=>g.id===id);if(group)group.collapsed=false}persistWorkspace();({page,query,kind,network,searched,selectedSource,tab,sourceMode}=t);render();const input=document.querySelector('#search-input');if(input)input.value=t.draft;for(const id of t.opened||[]){const d=document.querySelector(`[data-post="${id}"]`);if(d)d.open=true}window.SourceFeeds?.restoreOpen(document,t.liveOpened||[]);document.querySelector('#app').scrollTo(0,t.scroll||0);document.querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest',inline:'nearest'});}
function openView(view,key){saveView();if(!workspaceTabs.some(t=>t.key===key))workspaceTabs.push({key,...view,groupId:workspaceTabs.find(t=>t.key===activeKey)?.groupId||null});activateTab(key)}
function go(p){openView(emptyView(p,p==='Source'?selectedSource:null),p==='Source'?'Source:'+selectedSource:p);if(p==='Today')window.SourceFeeds?.refreshAll()}
function searchView(){const q=document.querySelector('#search-input').value.trim();if(window.searchSourceContent?.(q)||window.searchSavedCollection?.(q))return;const k=document.querySelector('#kind')?.value||'All types',n=document.querySelector('#network')?.value||'All platforms';const has=!!q||k!=='All types'||n!=='All platforms';if(!has)return go('Search');const key='Search:'+JSON.stringify([q.toLocaleLowerCase().replace(/\s+/g,' '),k,n]);openView({...emptyView('Search'),query:q,draft:q,kind:k,network:n,searched:true},key)}
function closeTab(key){const i=workspaceTabs.findIndex(t=>t.key===key);if(i<0)return;saveView();workspaceTabs.splice(i,1);if(!workspaceTabs.length)workspaceTabs.push({key:'Saved',...emptyView()});if(activeKey===key){activeKey='';activateTab(workspaceTabs[Math.min(i,workspaceTabs.length-1)].key)}else{persistWorkspace();render()}}
function tabLabel(t){return t.name||(t.page==='Source'?sources.find(s=>s.id===t.selectedSource)?.name||'Source':t.searched?t.query||[t.kind,t.network].filter(x=>!x.startsWith('All ')).join(' · '):t.page)}
function tabsView(){const drawTab=t=>{const label=tabLabel(t),i=workspaceTabs.indexOf(t);return `<div class="workspace-tab ${t.key===activeKey?'selected':''}" draggable="true" data-drag-tab="${esc(t.key)}"><button role="tab" aria-selected="${t.key===activeKey}" aria-controls="view-panel" id="workspace-tab-${i}" tabindex="${t.key===activeKey?0:-1}" data-workspace="${esc(t.key)}" title="${esc(label)}">${t.color?`<i class="tab-color" style="background:${TabTree.color(t.color)}"></i>`:icon(t.page==='Search'?'search':t.page==='Saved'?'save':'sources')}<span>${esc(label)}</span></button><button class="tab-options" data-tab-options="${esc(t.key)}" aria-label="Edit ${esc(label)} tab">${icon('more')}</button><button class="close-tab" data-close-tab="${esc(t.key)}" aria-label="Close ${esc(label)} tab">${icon('close')}</button></div>`};const drawGroup=(g,seen=new Set())=>{if(seen.has(g.id))return '';const visited=new Set([...seen,g.id]);return `<div class="workspace-group" data-drop-group="${g.id}"><div class="tab-group-heading"><button class="tab-group-toggle" data-toggle-tab-group="${g.id}" aria-expanded="${!g.collapsed}"><i class="tab-color" style="background:${g.color}"></i><span>${esc(g.name)}</span></button><button class="tab-options" data-edit-tab-group="${g.id}" aria-label="Edit ${esc(g.name)} group">${icon('more')}</button></div>${`<div class="tab-group-content" ${g.collapsed?'hidden':''}>${workspaceTabs.filter(t=>t.groupId===g.id).map(drawTab).join('')}${tabGroups.filter(c=>c.parentId===g.id).map(c=>drawGroup(c,visited)).join('')}</div>`}</div>`};return `<div class="workspace-tabs" role="tablist" aria-label="Open views"><div class="ungrouped-tabs" data-drop-group="">${workspaceTabs.filter(t=>!t.groupId).map(drawTab).join('')}</div>${tabGroups.filter(g=>!g.parentId).map(g=>drawGroup(g)).join('')}</div><button class="new-search" id="new-search" aria-label="New source search" title="New source search">${icon('plus')}</button><button class="new-search" id="organize-tabs" aria-label="Tab groups" title="Tab groups">${icon('folder')}</button>`}
function bindWorkspace(){document.querySelectorAll('[data-workspace]').forEach(e=>{e.onclick=()=>activateTab(e.dataset.workspace);e.onkeydown=event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const visible=[...document.querySelectorAll('[data-workspace]')].filter(e=>e.offsetParent!==null),i=visible.indexOf(e),next=event.key==='Home'?0:event.key==='End'?visible.length-1:(i+(event.key==='ArrowRight'?1:-1)+visible.length)%visible.length;activateTab(visible[next].dataset.workspace);document.querySelector('[role="tab"][aria-selected="true"]')?.focus()}}});document.querySelectorAll('[data-close-tab]').forEach(e=>e.onclick=()=>closeTab(e.dataset.closeTab));document.querySelectorAll('[data-tab-options]').forEach(e=>e.onclick=()=>editWorkspaceTab(e.dataset.tabOptions));document.querySelectorAll('[data-drag-tab]').forEach(e=>{e.oncontextmenu=event=>{event.preventDefault();editWorkspaceTab(e.dataset.dragTab)};e.ondragstart=event=>{event.dataTransfer.setData('application/x-workspace-tab',e.dataset.dragTab);event.dataTransfer.effectAllowed='move'}});document.querySelectorAll('[data-drop-group]').forEach(e=>{e.ondragover=event=>{if([...event.dataTransfer.types].includes('application/x-workspace-tab')){event.preventDefault();event.stopPropagation()}};e.ondrop=event=>{event.preventDefault();event.stopPropagation();const t=workspaceTabs.find(t=>t.key===event.dataTransfer.getData('application/x-workspace-tab'));if(!t)return;t.groupId=e.dataset.dropGroup||null;persistWorkspace();render()}});document.querySelectorAll('[data-toggle-tab-group]').forEach(e=>e.onclick=()=>{const g=tabGroups.find(g=>g.id===e.dataset.toggleTabGroup);g.collapsed=!g.collapsed;persistWorkspace();render()});document.querySelectorAll('[data-edit-tab-group]').forEach(e=>e.onclick=()=>editTabGroup(e.dataset.editTabGroup));document.querySelector('#organize-tabs').onclick=tabGroupManager;document.querySelector('#new-search').onclick=()=>{go('Search');document.querySelector('#search-input').focus()}}
function workspaceGroupOptions(selected=null,exclude=null){return `<option value="">No group</option>`+tabGroups.filter(g=>!exclude||TabTree.canParent(tabGroups,exclude,g.id)).map(g=>`<option value="${g.id}" ${selected===g.id?'selected':''}>${esc(TabTree.ancestors(tabGroups,g.id).reverse().map(id=>tabGroups.find(g=>g.id===id).name).join(' / '))}</option>`).join('')}
function editWorkspaceTab(key){const t=workspaceTabs.find(t=>t.key===key);if(!t)return;modal('Tab',`<form id="workspace-tab-form"><label class="category-field">Name<input id="workspace-tab-name" value="${esc(t.name||'')}" placeholder="${esc(tabLabel({...t,name:null}))}"></label><label class="category-field">Color<div class="workspace-color-fields"><input type="color" id="workspace-tab-color" value="${TabTree.color(t.color)}"><input id="workspace-tab-hex" aria-label="Tab color hex" value="${TabTree.color(t.color)}" pattern="#[a-fA-F0-9]{6}" required></div></label><label class="category-field">Group<select id="workspace-tab-group">${workspaceGroupOptions(t.groupId)}</select></label><div class="category-form-actions"><button type="button" id="reset-tab-style">Reset name & color</button><button class="btn">Save</button></div></form>`);syncWorkspaceColor('workspace-tab');document.querySelector('#workspace-tab-form').onsubmit=e=>{e.preventDefault();t.name=document.querySelector('#workspace-tab-name').value.trim()||null;t.color=document.querySelector('#workspace-tab-hex').value;t.groupId=document.querySelector('#workspace-tab-group').value||null;persistWorkspace();document.querySelector('#modal').close();render()};document.querySelector('#reset-tab-style').onclick=()=>{t.name=null;t.color=null;persistWorkspace();document.querySelector('#modal').close();render()}}
function syncWorkspaceColor(prefix){const picker=document.querySelector('#'+prefix+'-color'),hex=document.querySelector('#'+prefix+'-hex');picker.oninput=()=>hex.value=picker.value;hex.oninput=()=>{if(/^#[a-f0-9]{6}$/i.test(hex.value))picker.value=hex.value}}
function tabGroupManager(){modal('Tab groups',`<button class="btn" id="add-tab-group">${icon('plus')} Group</button><div class="workspace-group-list">${tabGroups.map(g=>`<div style="padding-left:${Math.min(6,TabTree.ancestors(tabGroups,g.id).length-1)*18}px"><i class="tab-color" style="background:${g.color}"></i><span>${esc(g.name)}</span><button data-subgroup="${g.id}" aria-label="Add subgroup to ${esc(g.name)}">${icon('plus')}</button><button data-manage-group="${g.id}" aria-label="Edit ${esc(g.name)} group">${icon('more')}</button></div>`).join('')}</div>`);document.querySelector('#add-tab-group').onclick=()=>editTabGroup();document.querySelectorAll('[data-subgroup]').forEach(e=>e.onclick=()=>editTabGroup(null,e.dataset.subgroup));document.querySelectorAll('[data-manage-group]').forEach(e=>e.onclick=()=>editTabGroup(e.dataset.manageGroup))}
function editTabGroup(id=null,parentId=null){const existing=tabGroups.find(g=>g.id===id),g=existing||{id:crypto.randomUUID(),name:'',color:'#ffffff',parentId};modal(existing?'Group':'New group',`<form id="tab-group-form"><label class="category-field">Name<input id="tab-group-name" required value="${esc(g.name)}"></label><label class="category-field">Color<div class="workspace-color-fields"><input type="color" id="tab-group-color" value="${g.color}"><input id="tab-group-hex" aria-label="Group color hex" value="${g.color}" pattern="#[a-fA-F0-9]{6}" required></div></label><label class="category-field">Parent group<select id="tab-group-parent">${workspaceGroupOptions(g.parentId,g.id)}</select></label><div class="category-form-actions">${existing?'<button type="button" id="remove-tab-group">Remove group</button>':''}<button class="btn">Save</button></div></form>`);syncWorkspaceColor('tab-group');document.querySelector('#tab-group-name').focus();document.querySelector('#tab-group-form').onsubmit=e=>{e.preventDefault();const parent=document.querySelector('#tab-group-parent').value||null;if(!TabTree.canParent(tabGroups,g.id,parent))return;g.name=document.querySelector('#tab-group-name').value.trim();if(!g.name)return;g.color=document.querySelector('#tab-group-hex').value;g.parentId=parent;if(!existing)tabGroups.push(g);persistWorkspace();document.querySelector('#modal').close();render()};document.querySelector('#remove-tab-group')?.addEventListener('click',()=>{const result=TabTree.remove(tabGroups,workspaceTabs,id);tabGroups=result.groups;workspaceTabs=result.tabs;persistWorkspace();document.querySelector('#modal').close();render()})}

function render(){cancelRecording();document.querySelector('.emoji-picker')?.remove();const names=['Sources','Saved','Files'];document.querySelector('#app').innerHTML=`<div class="layout"><aside class="sidebar" id="main-navigation"><button class="mobile-nav-close" id="close-navigation" aria-label="Close navigation">${icon('close')}</button><nav class="nav" aria-label="Main">${names.map((n,i)=>`<button class="${page===n||(['Today','Source','Read'].includes(page))&&n==='Sources'?'active':''}" ${n==='Files'?'disabled title="Files unavailable"':`data-page="${n}"`} ${page===n||(['Today','Source','Read'].includes(page))&&n==='Sources'?'aria-current="page"':''}>${icon(['sources','save','folder'][i])}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="profile-actions"><button class="profile-trigger" data-page="Profile"><span class="self-avatar"><span class="avatar">${profile.pfp?`<img class="avatar" src="${profile.pfp}" alt="">`:esc(profile.name.slice(0,1))}</span><span data-self-presence>${presenceDot(selfPresence())}</span></span><span class="profile-name">${esc(profile.name)}${settings.showUsername?`<small>@${esc(profile.username)}</small>`:''}</span></button>${interfaceFeatures.availability?`<button type="button" id="availability-toggle" aria-label="Open to" title="Open to: ${esc(availabilityChoices.find(([value])=>value===(profile.openTo||'unavailable'))?.[1]||'Not available')}" aria-haspopup="menu" aria-expanded="false" aria-controls="availability-menu"><span>${esc(availabilityLabel())}</span><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button>`:''}</div>${interfaceFeatures.availability?`<div id="availability-menu" role="menu" aria-label="Open to" hidden>${availabilityChoices.map(([value,label])=>`<button type="button" role="menuitemradio" aria-checked="${(profile.openTo||'unavailable')===value}" data-availability="${value}">${label}${(profile.openTo||'unavailable')===value?icon('check'):''}</button>`).join('')}</div>`:''}<button class="btn primary post-trigger" id="new-post" aria-label="Create post" title="Create post">${icon('plus')}</button>${mediaControlButtons()}</div></aside><button class="navigation-scrim" id="navigation-scrim" aria-label="Close navigation" tabindex="-1" hidden></button><main class="main"><div class="workspace-chrome"><header class="topbar"><button class="mobile-toggle" aria-label="Open navigation" id="mobile-menu" aria-expanded="false" aria-controls="main-navigation">${icon('menu')}</button>${tabsView()}</header><form id="search-form" class="searchbox">${icon('search')}<input id="search-input" aria-label="Search sources and media" placeholder="Search" value="${esc(query)}"><button type="button" class="filters-toggle" id="filters-toggle" aria-label="Filters" aria-expanded="false" aria-controls="search-filters">${icon('filters')}<span>Filters</span><span id="filter-count" hidden></span></button><button type="button" id="reverse" aria-label="Search by image">${icon('image')}</button><button type="submit" class="btn" aria-label="Run search">${icon('arrow')}</button></form><div class="advanced search-filters" id="search-filters" hidden><select id="kind" aria-label="Source type">${['All types','Person','Organization','Publication','Place','Thing'].map(n=>`<option ${kind===n?'selected':''}>${n}</option>`).join('')}</select><select id="network" aria-label="Platform">${[...new Set(['All platforms','Instagram','YouTube','YouTube community','Bandcamp','Spotify','Bandsintown','Bluesky','Mastodon','Reddit','X','RSS','Tumblr','Flickr','SoundCloud','Website','Custom / legacy link',...sources.flatMap(s=>(s.connections||[]).map(c=>c.platform))])].map(n=>`<option ${network===n?'selected':''}>${n}</option>`).join('')}</select></div></div><section id="view-panel" role="tabpanel" aria-labelledby="workspace-tab-${workspaceTabs.findIndex(t=>t.key===activeKey)}">${content()}</section></main></div>`;bind()}
function isEnabled(p){const s=sources.find(s=>s.id===p.source);if(!s?.saved)return false;if(p.live)return !!s.connections?.some(c=>c.id===p.connectionId&&c.enabled!==false);if(p.source!=='self'&&!p.member&&!interfaceFeatures.sampleSources)return false;return !s.disabled?.includes(s.links.indexOf(p.platform))}
function postListView(list){return window.SourceFeeds?SourceFeeds.view(list):list.map(postView).join('')}
let savedViewType='media';
function content(){
 if(page==='Saved'&&savedViewType==='media')return `${savedHeading()}<div id="saved-media-view"></div>`;
 if(page==='Source')return sourceView();if(page==='Profile')return profileView();if(page==='Settings')return settingsView();if(page==='Search'||page==='Sources')return sourcesView();
 let list=posts.filter(p=>page==='Saved'?saved.includes(p.id):isEnabled(p));if(page==='Read')list=list.filter(p=>read.includes(p.id));if(tab==='Unread'&&page!=='Read')list=list.filter(p=>!read.includes(p.id));
 return `${page==='Saved'?savedHeading():`<div class="page-title"><h1>${esc(page)}</h1></div>`}${page==='Read'?'':`<div class="filters">${['All updates','Unread'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}" aria-pressed="${tab===t}">${t}</button>`).join('')}<button class="filter-right" id="mark-all">Mark all as read</button></div>`}${list.length?postListView(list):page==='Today'&&window.SourceFeeds?.failures().length?'':'<div class="empty">No updates</div>'}`
}

function postView(p){const source=sources.find(s=>s.id===p.source);return `<details class="update" data-post="${p.id}"><summary><span class="update-source">${page==='Source'?esc(p.platform):`${esc(source.name)}<small>${p.platform}</small>`}</span><span class="update-time">${p.time}</span>${icon('plus')}</summary><div class="update-content"></div></details>`}
function expandedPost(p){return `<article class="post"><div class="post-body">${p.title?`<h2>${esc(p.title)}</h2>`:''}${p.text?`<p>${esc(p.text)}</p>`:''}${p.description?`<p class="post-description">${esc(p.description)}</p>`:''}${pollMarkup(p)}${postCulturalItems(p)}<div class="post-files">${(p.attachments||[]).map(a=>((a.type?.startsWith('video/')||a.type?.startsWith('audio/'))?`<${a.type.startsWith('video/')?'video':'audio'} class="post-media-preview" data-post-media="${a.id}" controls preload="metadata"></${a.type.startsWith('video/')?'video':'audio'}>`:'')+attachmentView(a)).join('')}</div>${p.type==='live'?'<span class="publish-note">Stream announcement</span>':''}</div>${p.image?`<img class="post-image" src="${p.image}" alt="${esc(p.alt)}">`:''}${openSourcePost(p)}<footer class="post-footer"><div class="post-actions"><button data-read="${p.id}">${icon('check')}${read.includes(p.id)?'Mark unread':'Mark read'}</button><button data-save="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} update" style="color:${saved.includes(p.id)?'#fff':'inherit'}">${icon('save')}</button>${p.url?`<a href="${p.url}" target="_blank" rel="noreferrer" aria-label="Open original">${icon('out')}</a>`:''}</div></footer></article>`}
function sourcesView(){const isSearch=page==='Search';return `<h1 class="sr-only">${isSearch?'Search results':'Sources'}</h1>${!isSearch?`<div class="folder-breadcrumb"><button data-page="Saved">${icon('arrow')} Saved</button></div>`:''}<div class="sources-toolbar sources-heading">${!isSearch?`<div class="source-view-options"><button class="btn today-option" data-page="Today">${icon('home')} Today</button><button class="btn read-option" data-page="Read">${icon('check')} Read</button></div>`:''}<div class="source-management">${!isSearch?`<button class="text-action" id="add-category">${icon('plus')} Category</button>`:''}<button class="btn" id="add-source">${icon('plus')} Import link</button></div></div><div id="source-results">${sourceResults()}</div>${searchedSourcePosts()}${isSearch&&searched&&query?`<section class="public-source-directory"><h2>Public sources</h2><div id="source-directory-results" data-query="${esc(query)}"></div></section>`:''}${isSearch&&searched&&query?`<section class="global-media-search"><div class="media-search-heading"><h2>Media</h2><select id="media-search-type" aria-label="Media search type"><option value="all">All media</option><option value="movie">Movies</option><option value="series">Shows</option><option value="music">Songs</option><option value="album">Albums</option><option value="artist">Artists</option><option value="book">Books</option><option value="game">Games</option></select></div><div id="media-search-results" data-query="${esc(query)}"></div></section>`:''}`}
function searchedSourcePosts(){if(page!=='Search'||!searched||!query)return '';const list=posts.filter(post=>{const source=sources.find(s=>s.id===post.source);return post.live&&source&&!source.redirectTo&&(saved.includes(post.id)||source.connections?.some(c=>c.id===post.connectionId&&c.enabled!==false))&&(kind==='All types'||source.type===kind)&&(network==='All platforms'||post.platform===network)&&SourceItemModel.matches(post,query)});return list.length?`<section class="source-search-updates"><h2>Updates</h2>${postListView(list)}</section>`:''}
function sourceResults(){if(page==='Search'&&!searched)return '';const list=sources.filter(s=>!s.redirectTo&&(page!=='Sources'||s.saved)&&(!query||`${s.name} ${(s.aliasNames||[]).join(' ')} ${s.links.join(' ')} ${(s.customLinks||[]).join(' ')} ${(s.connections||[]).map(c=>c.url).join(' ')} ${entityTags(s).map(t=>t.name).join(' ')}`.toLowerCase().includes(query.toLowerCase()))&&(kind==='All types'||s.type===kind)&&(network==='All platforms'||(network==='Custom / legacy link'?s.customLinks?.length:s.links.includes(network)||s.connections?.some(c=>c.platform===network))));return page==='Sources'?categoryTree(list):`<div class="source-grid">${list.map(sourceRow).join('')}</div>${!list.length?'<div class="empty">No sources</div>':''}`}
function profileView(){return `<div class="page-title"><div><h1>Profile</h1></div></div><section class="profile-card" style="background:${profile.color}"><div class="banner" ${profile.banner?`style="background-image:url('${profile.banner}')"`:''}><button class="btn upload-banner" id="banner-upload">${icon('image')} Change banner</button></div><div class="profile-content"><button class="profile-avatar" id="pfp-upload" style="background:${profile.accent}" aria-label="Upload profile picture">${profile.pfp?`<img src="${profile.pfp}" alt="Your profile picture">`:esc(profile.name.slice(0,1))}</button><div class="own-card-presence">${memberPresence({presence:selfPresence(),lastOnline})}</div>${interfaceFeatures.availability&&profile.openTo&&profile.openTo!=='unavailable'?`<div class="card-availability">Open to ${availabilityChoices.find(([v])=>v===profile.openTo)?.[1].toLowerCase()}</div>`:''}<input class="editable name" data-profile="name" aria-label="Display name" value="${esc(profile.name)}" maxlength="50"><input class="editable handle" data-profile="username" aria-label="Username" value="${esc(profile.username)}" maxlength="30"><div class="profile-fields"><label>TIMEZONE<input type="text" data-profile="timezone" value="${esc(profile.timezone)}" placeholder="America/New_York"></label><label>LOCATION<input type="text" data-profile="location" value="${esc(profile.location)}" placeholder="Your city"></label></div><fieldset class="pronoun-field"><legend>Pronouns</legend>${['he/him','she/her','they/them'].map(value=>`<label><input type="radio" name="pronouns" data-profile="pronouns" value="${value}" ${profile.pronouns===value?'checked':''}>${value}</label>`).join('')}</fieldset><div class="color-row"><label for="card-color">Card</label><input id="card-color" type="color" data-profile="color" value="${profile.color}"><label for="accent-color">Accent</label><input id="accent-color" type="color" data-profile="accent" value="${profile.accent}"></div></div></section>`}
function modal(title,body){const m=document.querySelector('#modal');m.classList.remove('library-dialog');m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button id="close-modal" aria-label="Close">${icon('close')}</button></div>${body}`;m.setAttribute('aria-labelledby','modal-title');m.showModal();document.querySelector('#close-modal').onclick=()=>m.close()}
function sourceModal(id){const s=sources.find(s=>s.id===id);if(window.SourceFeeds&&!s.member&&!s.matrixChatId&&!s.emailAccount)return SourceFeeds.manage(s);modal(esc(s.name),`${s.member?`<section class="member-profile-card"><div class="member-banner"></div><div class="member-card-content"><span class="member-card-avatar">${esc(s.initial)}</span><div class="member-handle">@${esc(s.username||s.name)}</div>${memberPresence(s)}</div></section>`:s.bio?`<p class="modal-intro">${esc(s.bio)}</p>`:''}<div id="links">${s.links.map((l,i)=>`<label class="link-row"><input type="checkbox" data-link="${i}" ${s.disabled?.includes(i)?'':'checked'}>${esc(l)}</label>`).join('')}</div><form id="custom-link"><input type="url" id="link-url" class="full" placeholder="https://… (any platform or archive)" required aria-label="Custom social link"><button class="btn full">${icon('plus')} Add another link</button></form><button class="btn primary full" id="modal-follow">${s.saved?'Remove from sources':'Add to sources'}</button>`);document.querySelectorAll('[data-link]').forEach(el=>el.onchange=()=>{s.disabled=s.disabled||[];const n=+el.dataset.link;s.disabled=el.checked?s.disabled.filter(x=>x!==n):[...s.disabled,n];persist();render();toast('Connection preference saved')});document.querySelector('#modal-follow').onclick=()=>{s.saved=!s.saved;persist();document.querySelector('#modal').close();render()};document.querySelector('#custom-link').onsubmit=e=>{e.preventDefault();const u=new URL(document.querySelector('#link-url').value);if(!['https:','http:'].includes(u.protocol))return toast('Use an http or https link');s.links.push(u.hostname.replace('www.',''));s.customLinks=s.customLinks||[];s.customLinks.push(u.href);persist();document.querySelector('#modal').close();sourceModal(id);render()}}
function importModal(){modal('Import source',`<form id="import-form"><input type="url" id="import-url" class="full" placeholder="https://…" aria-label="Source URL" required><input type="text" id="import-name" class="full" placeholder="Name (optional)" aria-label="Source name" maxlength="60"><button class="btn primary full">Add source ${icon('arrow')}</button></form>`);document.querySelector('#import-form').onsubmit=event=>{event.preventDefault();try{SourceFeeds.importURL(document.querySelector('#import-url').value,document.querySelector('#import-name').value)}catch(error){toast(error.message)}}}

function upload(callback){const f=document.createElement('input');f.type='file';f.onchange=()=>{const file=f.files[0];if(!file)return;const r=new FileReader();r.onload=()=>callback(r.result,file.name);r.onerror=()=>toast('Could not read file');r.readAsDataURL(file)};f.click()}
function bind(){window.PublicSourceUI?.bind();window.SourceFeeds?.bindLists();window.SourceFeeds?.directory();document.querySelector('#saved-posts')?.addEventListener('click',()=>{savedViewType='posts';render()});document.dispatchEvent(new Event('media-saved'));document.querySelector('#media-search-type')?.addEventListener('change',()=>document.dispatchEvent(new Event('media-search')));document.querySelector('#saved-media')?.addEventListener('click',()=>window.openSavedMedia?.());document.dispatchEvent(new Event('media-search'));bindEmail();bindMatrix();bindTags();bindPublicationView(document);bindCategories();bindCalls();bindAvailability();bindMediaControls();bindSettingsAndPost();bindMessaging();bindFilters();bindWorkspace();bindSourceOpen();bindUpdates();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceModal(b.dataset.source));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{const n=posts.find(p=>String(p.id)===b.dataset.read)?.id;read=read.includes(n)?read.filter(x=>x!==n):[...read,n];persist();render()});document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const n=posts.find(p=>String(p.id)===b.dataset.save)?.id;const exists=saved.includes(n);saved=exists?saved.filter(x=>x!==n):[...saved,n];persist();render();toast(exists?'Removed from saved':'Saved for later')});document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=()=>{const s=sources.find(s=>s.id===b.dataset.follow);s.saved=!s.saved;persist();render()});['add-source','side-add'].forEach(id=>{const e=document.getElementById(id);if(e)e.onclick=importModal});bindInterface();const all=document.querySelector('#mark-all');if(all)all.onclick=()=>{read=[...new Set([...read,...posts.filter(p=>(page==='Saved'?saved.includes(p.id):isEnabled(p))&&(page!=='Source'||p.source===selectedSource)&&(page!=='Saved'||saved.includes(p.id))&&(page!=='Read'||read.includes(p.id))).map(p=>p.id)])];persist();render();toast('Marked as read')};const form=document.querySelector('#search-form');if(form)form.onsubmit=e=>{e.preventDefault();searchView()};const rev=document.querySelector('#reverse');if(rev)rev.onclick=()=>modal('Image search',`<button class="btn full" id="reverse-upload">${icon('image')} Choose an image</button><div id="reverse-result"></div>` )||null; if(rev){const old=rev.onclick;rev.onclick=()=>{if(window.SourceFeeds){SourceFeeds.imageSearch();return}old();document.querySelector('#reverse-upload').onclick=()=>upload((data,name)=>{document.querySelector('#reverse-result').innerHTML=`<div class="image-result"><img src="${data}" alt="Selected image" style="width:100%;max-height:180px;object-fit:contain"><p>${esc(name)}</p><p>Image search unavailable.</p></div>`;})}}document.querySelectorAll('[data-profile]').forEach(e=>e.oninput=()=>{profile[e.dataset.profile]=e.value;persist();if(e.dataset.profile==='color')document.querySelector('.profile-card').style.background=e.value;if(e.dataset.profile==='accent')document.querySelector('.profile-avatar').style.background=e.value});['banner','pfp'].forEach(k=>{const e=document.querySelector('#'+k+'-upload');if(e)e.onclick=()=>upload(data=>{profile[k]=data;persist();render()})});}
function bindFilters(){const button=document.querySelector('#filters-toggle'),panel=document.querySelector('#search-filters');const refresh=()=>{const count=Number(document.querySelector('#kind').value!=='All types')+Number(document.querySelector('#network').value!=='All platforms');const badge=document.querySelector('#filter-count');badge.textContent=count;badge.hidden=!count;button.classList.toggle('has-filters',!!count)};button.onclick=()=>{panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden))};panel.onkeydown=e=>{if(e.key==='Escape'){panel.hidden=true;button.setAttribute('aria-expanded','false');button.focus()}};panel.querySelectorAll('select').forEach(e=>e.onchange=refresh);refresh()}
function bindResults(){bindTags();bindCategories();bindMessaging();bindSourceOpen();document.querySelectorAll('#source-results [data-source]').forEach(b=>b.onclick=()=>sourceModal(b.dataset.source));document.querySelectorAll('#source-results [data-follow]').forEach(b=>b.onclick=()=>{const s=sources.find(s=>s.id===b.dataset.follow);s.saved=!s.saved;persist();render()})}
function sourceView(){const source=sources.find(s=>s.id===selectedSource);if(!source)return '<div class="empty">Source unavailable</div>';if(source.emailAccount)return emailSourceView(source);if(source.matrixChatId)return matrixSourceView(source);if(!source.member&&window.PublicSourceUI)return PublicSourceUI.view(source);const list=posts.filter(p=>isEnabled(p)&&p.source===source.id&&(tab!=='Unread'||!read.includes(p.id)));return `<div class="page-title"><h1>${esc(source.name)}</h1><div class="source-header-actions"><button class="btn" data-tag-source="${source.id}" aria-label="Tags for ${esc(source.name)}">${icon('tag')}</button>${source.member&&source.id!=='self'?`<button class="btn" id="start-call">${icon('phone')} Call</button>`:''}<button class="btn" data-source="${source.id}">About & links</button></div></div>${source.member?`<div class="source-modes"><button data-source-mode="Updates" class="${sourceMode==='Updates'?'active':''}">Updates</button>${source.id==='self'?`<button data-source-mode="Scheduled" class="${sourceMode==='Scheduled'?'active':''}">Scheduled</button>`: `<button data-source-mode="Messages" class="${sourceMode==='Messages'?'active':''}">${icon('message')} Messages</button>`}</div>`:''}${source.id==='self'&&sourceMode==='Scheduled'?scheduledPostsView():source.member&&sourceMode==='Messages'?conversationView(source):`<div class="filters">${['All updates','Unread'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${list.length?postListView(list):'<div class="empty">No updates</div>'}`}`}
const pendingFiles={},mediaUrls=new Map();let recording=null,mediaDatabase;
const formatDuration=n=>`${Math.floor((n||0)/60)}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
const fileSize=n=>{if(n<1024)return n+' B';const units=['KB','MB','GB','TB'];let value=n/1024,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++}return value.toFixed(value<10?1:0)+' '+units[index]};
function openMediaDB(){if(!mediaDatabase)mediaDatabase=new Promise((resolve,reject)=>{const r=indexedDB.open('daily-message-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return mediaDatabase}
async function storeMedia(id,blob){const db=await openMediaDB();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function mediaUrl(id){if(mediaUrls.has(id))return mediaUrls.get(id);const db=await openMediaDB();const blob=await new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!blob)throw Error('Attachment unavailable');const url=URL.createObjectURL(blob);mediaUrls.set(id,url);return url}
function attachmentView(a){if(a.kind==='gif')return `<div class="gif-message"><img src="${esc(a.url)}" alt="${esc(a.name)}" loading="lazy"><span>GIF</span></div>`;if(a.kind==='voice')return `<div class="voice-clip" data-media="${esc(a.id)}"><button type="button" class="voice-play" aria-label="Play voice message">${icon('play')}</button><div class="voice-track"><div class="voice-wave" aria-hidden="true">${Array.from({length:32},(_,i)=>`<i style="height:${Math.max(4,Math.round((a.wave?.[i]||0.1)*26))}px"></i>`).join('')}</div><input class="voice-seek" type="range" min="0" max="${a.duration||1}" step="0.1" value="0" aria-label="Voice message position"></div><span class="voice-time">${formatDuration(a.duration)}</span><audio preload="metadata"></audio></div>`;return `<div class="file-attachment" data-media="${esc(a.id)}">${a.type.startsWith('image/')?'<img class="attached-image" alt="'+esc(a.name)+'" loading="lazy">':icon('file')}<div><a class="file-download" download="${esc(a.name)}">${esc(a.name)}</a><small>${fileSize(a.size)}</small></div>${icon('download')}</div>`}
function reactionView(m){return `<div class="reactions">${Object.entries(m.reactions||{}).filter(([,n])=>n).map(([emoji])=>`<button type="button" class="reaction selected" data-react-message="${m.id}" data-emoji="${esc(emoji)}" aria-label="Remove ${esc(emoji)} reaction" aria-pressed="true">${esc(emoji)} <span>1</span></button>`).join('')}</div>`}
const actorId=new URLSearchParams(location.search).get('participant')==='member-maya'?'member-maya':'self';
const messageAuthor=m=>m.author||'self';
const authorName=id=>id==='self'?profile.name:sources.find(s=>s.id===id)?.name||'Member';
const conversationPartner=s=>actorId==='self'?s.name:profile.name;
let editingMessage=null;const editingDrafts={},revealedMessages=new Set(),typingPeers=new Map();let typingTimer,readObserver;
const messageEvents=typeof BroadcastChannel==='function'?new BroadcastChannel('daily-conversations'):null;
function syncConversations(){try{const data=JSON.parse(localStorage.getItem('daily-mockup')||'{}');conversations=data.conversations||conversations}catch{}}
function announceTyping(active){const sourceId=selectedSource;messageEvents?.postMessage({type:'typing',sourceId,actorId,active});clearTimeout(typingTimer);if(active)typingTimer=setTimeout(()=>messageEvents?.postMessage({type:'typing',sourceId,actorId,active:false}),3500)}
function renderTyping(){const el=document.querySelector('#typing-status');if(!el)return;const active=[...typingPeers.values()].filter(p=>p.sourceId===selectedSource&&p.actorId!==actorId&&p.until>Date.now());el.innerHTML=active.length?`<span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>${esc(authorName(active[0].actorId))} is typing</span>`:''}
if(messageEvents)messageEvents.onmessage=e=>{const m=e.data;if(m?.type!=='typing'||m.actorId===actorId)return;const key=m.sourceId+':'+m.actorId;typingPeers.set(key,{...m,until:m.active?Date.now()+5000:0});renderTyping();setTimeout(renderTyping,5100)};
function messageTime(time,full=true){const options={...(full?{month:'short',day:'numeric'}:{}),hour:'numeric',minute:'2-digit'};if(settings.messagePrecision!=='minutes')options.second='2-digit';if(settings.messagePrecision==='milliseconds')options.fractionalSecondDigits=3;try{options.timeZone=profile.timezone;return new Intl.DateTimeFormat(undefined,options).format(new Date(time))}catch{delete options.timeZone;return new Intl.DateTimeFormat(undefined,options).format(new Date(time))}}
function receiptView(messages){const m=[...messages].reverse().find(m=>messageAuthor(m)===actorId);if(!m)return '';const seen=(m.readBy||[]).find(id=>id!==actorId);return `<div class="read-receipt" data-receipt="${m.id}">${seen?`${icon('check')} Read`:'Sent'}</div>`}
function messageMarkup(messages){messages.forEach((m,i)=>m.id||='legacy-'+i);return (messages.length?messages.map((m,i)=>{const author=messageAuthor(m),own=author===actorId,previous=messages[i-1],grouped=previous&&messageAuthor(previous)===author&&new Date(m.time)-new Date(previous.time)<300000;const show=!m.retractedAt||revealedMessages.has(m.id);const edit=editingMessage===m.id;return `<article class="chat-message ${grouped?'grouped':''}" data-chat-id="${m.id}">${grouped?'<span class="group-gutter"></span>':`<span class="avatar">${esc(authorName(author).slice(0,1))}</span>`}<div class="message-main">${grouped&&settings.messagePrecision!=='minutes'?`<time class="grouped-timestamp" datetime="${m.time}">${esc(messageTime(m.time,false))}</time>`:''}${!grouped?`<header><span class="message-author"><strong>${esc(authorName(author))}</strong>${author==='self'?(settings.showUsername?`<small>@${esc(profile.username)}</small>`:''):`<small>@${esc(sources.find(s=>s.id===author)?.username||'')}</small>`}</span><time datetime="${esc(m.time)}">${esc(messageTime(m.time,false))}</time></header>`:''}${m.retractedAt?`<div class="retracted-label">Message retracted <button type="button" data-reveal-message="${m.id}" aria-expanded="${show}">${show?'Hide message':'View message'}</button></div>`:''}${edit?`<form class="edit-message-form" data-edit-form="${m.id}"><textarea aria-label="Edit message" maxlength="4000" rows="2">${esc(editingDrafts[m.id]??m.text)}</textarea><div><button type="button" data-cancel-edit="${m.id}">Cancel</button><button type="submit" class="btn">Save</button></div></form>`:show?`${m.text?`<p class="${m.retractedAt?'retracted-content':''}">${esc(m.text)}</p>`:''}<div class="message-attachments">${(m.attachments||[]).map(attachmentView).join('')}</div>`:''}${m.editedAt?`<button class="edited-label" type="button" data-edit-history="${m.id}" aria-label="View edit history">edited</button>`:''}${!m.retractedAt?reactionView(m):''}</div><div class="message-tools">${!m.retractedAt?`<button type="button" class="add-reaction" data-reaction-picker="${m.id}" aria-label="Add reaction" title="Add reaction">${icon('smile')}</button>${own?`<button type="button" data-edit-message="${m.id}" aria-label="Edit message" title="Edit">${icon('edit')}</button><button type="button" data-retract-message="${m.id}" aria-label="Retract message" title="Retract">${icon('retract')}</button>`:''}`:''}</div></article>`}).join(''):'<span class="empty">No messages</span>')+receiptView(messages)}
function refreshMessageList(){if(sources.find(s=>s.id===selectedSource)?.matrixChatId)return;const history=document.querySelector('.message-history');if(!history)return;const atEnd=history.scrollHeight-history.scrollTop-history.clientHeight<80,y=history.scrollTop;history.innerHTML=messageMarkup(conversations[selectedSource]||[]);bindMessageActions();hydrateMedia(history);history.scrollTop=atEnd?history.scrollHeight:y;observeReadMessages()}
function observeReadMessages(){readObserver?.disconnect();const history=document.querySelector('.message-history');if(!history||document.hidden||!document.hasFocus()||!navigator.onLine)return;readObserver=new IntersectionObserver(entries=>{if(document.hidden||!document.hasFocus()||!navigator.onLine)return;const visible=entries.filter(e=>e.isIntersecting&&e.intersectionRatio>=.6).map(e=>e.target.dataset.chatId);if(!visible.length)return;syncConversations();let changed=false;for(const m of conversations[selectedSource]||[]){if(visible.includes(m.id)&&messageAuthor(m)!==actorId&&!(m.readBy||[]).includes(actorId)){(m.readBy||=[]).push(actorId);changed=true}}if(changed)persist()},{root:history,threshold:.6});history.querySelectorAll('[data-chat-id]').forEach(e=>readObserver.observe(e))}
window.addEventListener('storage',e=>{if(e.key!=='daily-mockup')return;syncConversations();refreshMessageList()});
window.addEventListener('focus',observeReadMessages);document.addEventListener('visibilitychange',()=>{if(document.hidden)announceTyping(false);else observeReadMessages()});window.addEventListener('pagehide',()=>announceTyping(false));
function bindMessageActions(){const find=id=>(conversations[selectedSource]||[]).find(m=>m.id===id);document.querySelectorAll('[data-edit-message]').forEach(b=>b.onclick=()=>{const m=find(b.dataset.editMessage);if(messageAuthor(m)!==actorId||m.retractedAt)return;editingMessage=m.id;editingDrafts[m.id]=m.text;refreshMessageList();document.querySelector('.edit-message-form textarea').focus()});document.querySelectorAll('[data-cancel-edit]').forEach(b=>b.onclick=()=>{delete editingDrafts[b.dataset.cancelEdit];editingMessage=null;refreshMessageList()});document.querySelectorAll('[data-edit-form]').forEach(form=>{const input=form.querySelector('textarea');input.oninput=()=>editingDrafts[form.dataset.editForm]=input.value;input.onkeydown=e=>{if(e.key==='Escape'){editingMessage=null;refreshMessageList()}else if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();form.requestSubmit()}};form.onsubmit=e=>{e.preventDefault();syncConversations();const m=find(form.dataset.editForm),text=input.value.trim();if(!m||messageAuthor(m)!==actorId||m.retractedAt)return;if(!text&&!m.attachments?.length)return;if(text!==m.text){m.revisions||=[{text:m.text,time:m.time}];const time=new Date().toISOString();m.revisions.push({text,time});m.text=text;m.editedAt=time;m.readBy=[actorId];persist()}editingMessage=null;delete editingDrafts[m.id];refreshMessageList()}});document.querySelectorAll('[data-retract-message]').forEach(b=>b.onclick=()=>{syncConversations();const m=find(b.dataset.retractMessage);if(!m||messageAuthor(m)!==actorId)return;m.retractedAt=new Date().toISOString();persist();refreshMessageList()});document.querySelectorAll('[data-reveal-message]').forEach(b=>b.onclick=()=>{const id=b.dataset.revealMessage;revealedMessages.has(id)?revealedMessages.delete(id):revealedMessages.add(id);refreshMessageList()});document.querySelectorAll('[data-edit-history]').forEach(b=>b.onclick=()=>{const m=find(b.dataset.editHistory);modal('Edit history',`<div class="edit-history">${(m.revisions||[]).map((r,i)=>`<article><header><span>${i===0?'Original':i===m.revisions.length-1?'Current':'Revision '+i}</span><time>${esc(messageTime(r.time))}</time></header><p>${esc(r.text)||'No text'}</p></article>`).join('')}</div>`)});document.querySelectorAll('[data-reaction-picker]').forEach(button=>button.onclick=()=>emojiPicker(button,emoji=>{syncConversations();const m=find(button.dataset.reactionPicker);m.reactions||={};m.reactions[emoji]=!m.reactions[emoji];persist();refreshMessageList()}));document.querySelectorAll('[data-react-message]').forEach(button=>button.onclick=()=>{syncConversations();const m=find(button.dataset.reactMessage);m.reactions[button.dataset.emoji]=false;persist();refreshMessageList()})}

function conversationView(source){return `<section class="conversation" aria-label="Conversation with ${esc(conversationPartner(source))}"><div id="call-space">${callStateView()}</div><div class="message-history" role="log" aria-live="polite">${messageMarkup(conversations[source.id]||[])}</div><div id="typing-status" role="status" aria-live="polite"></div><div class="composer-area"><div id="attachment-drafts"></div><div class="recording-controls" id="recording-controls" hidden><span class="record-indicator"></span><span id="record-time">0:00</span><span class="record-wave" aria-hidden="true">▂ ▅ ▃ ▇ ▄ ▂ ▆ ▃</span><button type="button" id="discard-recording" aria-label="Discard recording">${icon('trash')}</button><button type="button" id="stop-recording" class="btn">Stop</button></div><form id="message-form"><button type="button" id="attach-files" class="composer-icon" aria-label="Attach files" title="Attach files">${icon('plus')}</button><input type="file" id="file-input" multiple hidden><textarea id="message-input" aria-label="Message ${esc(conversationPartner(source))}" placeholder="Message ${esc(conversationPartner(source))}" rows="1" maxlength="4000">${esc(messageDrafts[source.id]||'')}</textarea><button type="button" id="compose-emoji" class="composer-icon" aria-label="Add emoji" title="Add emoji">${icon('smile')}</button><button type="button" id="compose-gif" class="composer-icon gif-button" aria-label="Send GIF" title="GIF">GIF</button><button type="button" id="record-voice" class="composer-icon" aria-label="Record voice message" title="Click to record, or hold and release to send">${icon('mic')}</button><button type="submit" class="composer-icon send-message" aria-label="Send message">${icon('send')}</button></form></div></section>`}
function drawPending(){const holder=document.querySelector('#attachment-drafts');if(!holder)return;const list=pendingFiles[selectedSource]||[];holder.innerHTML=list.map((a,i)=>`<div class="pending-attachment">${attachmentView(a)}<button type="button" data-remove-file="${i}" aria-label="Remove ${esc(a.name)}">${icon('close')}</button></div>`).join('');holder.querySelectorAll('[data-remove-file]').forEach(e=>e.onclick=()=>{pendingFiles[selectedSource].splice(+e.dataset.removeFile,1);drawPending()});hydrateMedia(holder);updateSend()}
function updateSend(){const button=document.querySelector('.send-message');if(button)button.disabled=!document.querySelector('#message-input').value.trim()&&!(pendingFiles[selectedSource]||[]).length}
async function addFiles(files,sourceId){for(const f of files){try{const a={id:crypto.randomUUID(),name:f.name,type:f.type||'application/octet-stream',size:f.size,kind:'file'};await storeMedia(a.id,f);(pendingFiles[sourceId]||= []).push(a)}catch(e){toast(e.name==='QuotaExceededError'?'Device storage is full. Attachment not added.':'Could not save attachment')}}if(sourceId===selectedSource)drawPending()}
async function hydrateMedia(root=document){for(const el of root.querySelectorAll('[data-media]')){try{const url=await mediaUrl(el.dataset.media);if(!el.isConnected)continue;if(el.classList.contains('voice-clip')){const audio=el.querySelector('audio'),button=el.querySelector('.voice-play'),seek=el.querySelector('.voice-seek'),time=el.querySelector('.voice-time');audio.src=url;audio.muted=mediaControls.deafened;button.onclick=async()=>{try{if(audio.paused){document.querySelectorAll('audio').forEach(other=>{if(other!==audio)other.pause()});await audio.play()}else audio.pause()}catch{toast('Audio playback unavailable')}};audio.onplay=()=>{button.innerHTML=icon('pause');button.setAttribute('aria-label','Pause voice message')};audio.onpause=audio.onended=()=>{button.innerHTML=icon('play');button.setAttribute('aria-label','Play voice message')};audio.onloadedmetadata=()=>{if(Number.isFinite(audio.duration)&&audio.duration>0)seek.max=audio.duration};audio.ontimeupdate=()=>{seek.value=audio.currentTime;time.textContent=formatDuration(audio.currentTime);el.style.setProperty('--played',Math.min(100,100*audio.currentTime/Number(seek.max))+'%')};seek.oninput=()=>{audio.currentTime=Number(seek.value)};audio.onerror=()=>{button.disabled=true;time.textContent='Unavailable'}}else{const a=el.querySelector('a');a.href=url;const img=el.querySelector('img');if(img)img.src=url}}catch{el.classList.add('media-missing');el.title='Attachment unavailable on this device'}}}
function emojiPicker(anchor,onChoose){document.querySelector('.emoji-picker')?.remove();const picker=document.createElement('div');picker.className='emoji-picker';picker.setAttribute('role','dialog');picker.setAttribute('aria-label','Choose emoji');picker.innerHTML=['👍','❤️','😂','🙌','👀','🔥','✨','🎉','🤔','💀','😭','✅'].map(e=>`<button type="button" aria-label="${e}">${e}</button>`).join('')+'<button type="button" class="emoji-close" aria-label="Close emoji picker">×</button>';document.body.append(picker);const r=anchor.getBoundingClientRect();picker.style.left=Math.max(12,Math.min(innerWidth-248,r.left-100))+'px';picker.style.top=Math.max(12,Math.min(innerHeight-170,r.top-160))+'px';picker.querySelectorAll('button').forEach(button=>button.onclick=()=>{if(!button.classList.contains('emoji-close'))onChoose(button.textContent);picker.remove();anchor.isConnected&&anchor.focus()});picker.onkeydown=e=>{if(e.key==='Escape'){picker.remove();anchor.focus()}};const outside=e=>{if(!picker.contains(e.target)&&e.target!==anchor){picker.remove();document.removeEventListener('pointerdown',outside)}};setTimeout(()=>document.addEventListener('pointerdown',outside),0);picker.querySelector('button').focus()}
function cancelRecording(){if(!recording)return;recording.discard=true;if(recording.recorder?.state==='recording')recording.recorder.stop();recording.stream?.getTracks().forEach(t=>t.stop());clearInterval(recording.timer);recording=null}
async function voicePeaks(blob){try{const context=new OfflineAudioContext(1,1,22050),buffer=await context.decodeAudioData(await blob.arrayBuffer()),data=buffer.getChannelData(0),step=Math.max(1,Math.floor(data.length/32));const peaks=Array.from({length:32},(_,i)=>{let peak=0;for(let n=i*step;n<Math.min((i+1)*step,data.length);n++)peak=Math.max(peak,Math.abs(data[n]));return peak});const max=Math.max(.01,...peaks);return {wave:peaks.map(n=>n/max),duration:buffer.duration}}catch{return {}}}
async function startRecording(){if(mediaControls.muted){toast('Unmute to record a voice message');return}if(recording)return;const state={sourceId:selectedSource,started:performance.now(),chunks:[],discard:false};recording=state;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('unsupported');state.stream=await navigator.mediaDevices.getUserMedia({audio:true});if(recording!==state){state.stream.getTracks().forEach(t=>t.stop());return}const type=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));state.recorder=new MediaRecorder(state.stream,type?{mimeType:type}:undefined);state.recorder.ondataavailable=e=>{if(e.data.size)state.chunks.push(e.data)};state.recorder.onstop=async()=>{state.stream.getTracks().forEach(t=>t.stop());clearInterval(state.timer);if(recording===state)recording=null;document.querySelector('#recording-controls')?.setAttribute('hidden','');document.querySelector('#record-voice')?.setAttribute('aria-pressed','false');if(state.discard)return;try{const blob=new Blob(state.chunks,{type:state.recorder.mimeType});if(!blob.size)return;const a={id:crypto.randomUUID(),kind:'voice',name:'Voice message',type:blob.type,size:blob.size,duration:(performance.now()-state.started)/1000};Object.assign(a,await voicePeaks(blob));await storeMedia(a.id,blob);(pendingFiles[state.sourceId]||=[]).push(a);if(state.sourceId===selectedSource&&document.querySelector('#message-form')){drawPending();if(state.sendOnStop)sendMessage()}}catch{toast('Could not save recording')}};state.started=performance.now();state.recorder.start();document.querySelector('#recording-controls').hidden=false;document.querySelector('#record-voice').setAttribute('aria-pressed','true');state.timer=setInterval(()=>{const time=document.querySelector('#record-time');if(time)time.textContent=formatDuration((performance.now()-state.started)/1000);},250);if(state.releaseRequested)stopRecording(state.sendOnStop)}catch(e){state.stream?.getTracks().forEach(t=>t.stop());if(recording===state)recording=null;toast(e.name==='NotAllowedError'?'Microphone permission is required':e.name==='NotFoundError'?'No microphone found':'Voice recording unavailable')}}
function stopRecording(send){if(!recording)return;recording.sendOnStop=send;if(recording.recorder?.state==='recording')recording.recorder.stop();else recording.releaseRequested=true}
function sendMessage(){const input=document.querySelector('#message-input');if(!input||recording)return;const text=input.value.trim(),attachments=pendingFiles[selectedSource]||[];if(!text&&!attachments.length)return;syncConversations();announceTyping(false);(conversations[selectedSource]||=[]).push({id:crypto.randomUUID(),text,time:new Date().toISOString(),attachments,reactions:{},author:actorId,readBy:[actorId]});messageDrafts[selectedSource]='';pendingFiles[selectedSource]=[];persist();render();document.querySelector('#message-input')?.focus();const history=document.querySelector('.message-history');history.scrollTop=history.scrollHeight}
function bindMessaging(){document.querySelectorAll('[data-message-source]').forEach(e=>e.onclick=()=>{selectedSource=e.dataset.messageSource;go('Source');sourceMode='Messages';render();document.querySelector('#message-input').focus()});document.querySelectorAll('[data-source-mode]').forEach(e=>e.onclick=()=>{cancelRecording();sourceMode=e.dataset.sourceMode;render()});const input=document.querySelector('#message-input'),form=document.querySelector('#message-form');if(!form)return;document.querySelector('#attach-files').onclick=()=>document.querySelector('#file-input').click();document.querySelector('#file-input').onchange=e=>{addFiles([...e.target.files],selectedSource);e.target.value=''};input.oninput=()=>{messageDrafts[selectedSource]=input.value;announceTyping(!!input.value.trim());input.style.height='auto';input.style.height=Math.min(input.scrollHeight,180)+'px';updateSend()};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}};form.onsubmit=e=>{e.preventDefault();sendMessage()};document.querySelector('#compose-emoji').onclick=e=>emojiPicker(e.currentTarget,emoji=>{const start=input.selectionStart,end=input.selectionEnd;input.setRangeText(emoji,start,end,'end');input.dispatchEvent(new Event('input'));input.focus()});document.querySelector('#compose-gif').onclick=gifPicker;const mic=document.querySelector('#record-voice');let pressedAt=0;mic.onpointerdown=e=>{if(e.button!==0||recording)return;pressedAt=performance.now();mic.setPointerCapture(e.pointerId);startRecording()};mic.onpointerup=()=>{if(performance.now()-pressedAt>350&&recording)stopRecording(true)};mic.onpointercancel=cancelRecording;mic.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();recording?stopRecording(false):startRecording()}};document.querySelector('#discard-recording').onclick=()=>{cancelRecording();document.querySelector('#recording-controls').hidden=true;mic.setAttribute('aria-pressed','false')};document.querySelector('#stop-recording').onclick=()=>stopRecording(false);bindMessageActions();renderTyping();observeReadMessages();form.ondragover=e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();form.classList.add('dragging')}};form.ondragleave=()=>form.classList.remove('dragging');form.ondrop=e=>{e.preventDefault();form.classList.remove('dragging');addFiles([...e.dataTransfer.files],selectedSource)};drawPending();hydrateMedia(document.querySelector('.message-history'))}

function bindSourceOpen(){document.querySelectorAll('[data-open-source]').forEach(b=>b.onclick=()=>{selectedSource=b.dataset.openSource;go('Source')})}
function bindUpdates(){document.querySelectorAll('[data-post]').forEach(d=>d.ontoggle=()=>{const target=d.querySelector('.update-content');if(!d.open){target.innerHTML='';return}const p=posts.find(p=>String(p.id)===d.dataset.post);target.innerHTML=expandedPost(p);bindPublicationView(target);target.querySelector('[data-read]').onclick=()=>{read=read.includes(p.id)?read.filter(n=>n!==p.id):[...read,p.id];persist();const y=document.querySelector('#app').scrollTop;render();const reopened=document.querySelector(`[data-post="${p.id}"]`);if(reopened)reopened.open=true;document.querySelector('#app').scrollTo(0,y)};target.querySelector('[data-save]').onclick=e=>{const exists=saved.includes(p.id);saved=exists?saved.filter(n=>n!==p.id):[...saved,p.id];persist();e.currentTarget.style.color=exists?'':'#fff';e.currentTarget.setAttribute('aria-label',exists?'Save update':'Unsave update');toast(exists?'Removed from saved':'Saved')}})}
function settingsView(){return `<div class="page-title"><h1>Settings</h1></div><div class="settings-panel"><section><h2>Profile</h2><label class="setting-row"><span>Show my username</span><input type="checkbox" id="show-username" ${settings.showUsername?'checked':''} role="switch"></label></section><section><h2>Messages</h2><label class="setting-row"><span>Timestamp precision</span><select id="message-precision">${[['minutes','Minutes'],['seconds','Seconds'],['milliseconds','Milliseconds']].map(([v,l])=>`<option value="${v}" ${settings.messagePrecision===v?'selected':''}>${l}</option>`).join('')}</select></label><time class="timestamp-preview">${esc(messageTime(new Date().toISOString()))}</time></section>${matrixSettings()}<section><h2>Data</h2><div class="backup-actions"><button class="text-action" id="backup-export">Export backup</button><label class="text-action">Restore backup<input type="file" id="backup-import" accept="application/json,.json" hidden></label></div><div id="backup-status" role="status"></div></section></div>`}
function bindSettingsAndPost(){window.NavBackup?.bind();document.querySelector('#new-post').onclick=postComposer;const name=document.querySelector('#show-username');if(name)name.onchange=()=>{settings.showUsername=name.checked;persist();render();document.querySelector('#show-username').focus()};const precision=document.querySelector('#message-precision');if(precision)precision.onchange=()=>{settings.messagePrecision=precision.value;persist();render();document.querySelector('#message-precision').focus()}}
const gifCollection=[{name:'Hello',url:'assets/hello.gif',tags:'hello hi wave greeting'},{name:'Celebrate',url:'assets/celebrate.gif',tags:'celebrate party yes cheers'},{name:'Thanks',url:'assets/thanks.gif',tags:'thanks thank you heart love'},{name:'Loading',url:'assets/loading.gif',tags:'loading wait thinking'}];
function gifPicker(){modal('GIFs',`<form id="gif-search" class="gif-search"><input type="text" id="gif-query" placeholder="Search GIFs" aria-label="Search GIFs"><button class="btn" aria-label="Search GIFs">${icon('search')}</button></form><div id="gif-results" class="gif-grid"></div>`);const show=()=>{const query=document.querySelector('#gif-query').value.trim().toLowerCase(),list=gifCollection.filter(g=>!query||g.tags.includes(query)||g.name.toLowerCase().includes(query));document.querySelector('#gif-results').innerHTML=list.map(g=>`<button type="button" data-gif="${gifCollection.indexOf(g)}" aria-label="Send ${esc(g.name)} GIF"><img src="${g.url}" alt="${g.name}"><span>${g.name}</span></button>`).join('')||'<div class="empty">No GIFs</div>';document.querySelectorAll('[data-gif]').forEach(b=>b.onclick=()=>{const g=gifCollection[+b.dataset.gif];(pendingFiles[selectedSource]||=[]).push({id:crypto.randomUUID(),kind:'gif',name:g.name,url:g.url});document.querySelector('#modal').close();drawPending();sendMessage()})};document.querySelector('#gif-search').onsubmit=e=>{e.preventDefault();show()};show();document.querySelector('#gif-query').focus()}

const availabilityChoices=[['chat','Chat'],['calls','Calls'],['both','Chat & calls'],['unavailable','Not available']];
function availabilityLabel(){return profile.openTo==='chat'?'Open to chat':profile.openTo==='calls'?'Open to calls':profile.openTo==='both'?'Chat & calls':'Unavailable'}
function bindAvailability(){const toggle=document.querySelector('#availability-toggle'),menu=document.querySelector('#availability-menu');if(!toggle||!menu)return;const close=()=>{menu.hidden=true;toggle.setAttribute('aria-expanded','false')};toggle.onclick=()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)menu.querySelector('[aria-checked="true"]').focus()};menu.querySelectorAll('[data-availability]').forEach(button=>button.onclick=()=>{profile.openTo=button.dataset.availability;persist();render();document.querySelector('#availability-toggle').focus()});menu.onkeydown=e=>{const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close();toggle.focus()}else if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus()}};toggle.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();menu.hidden=false;toggle.setAttribute('aria-expanded','true');menu.querySelector('button').focus()}}}
document.addEventListener('pointerdown',e=>{const menu=document.querySelector('#availability-menu'),toggle=document.querySelector('#availability-toggle');if(menu&&!menu.contains(e.target)&&!toggle?.contains(e.target)){menu.hidden=true;toggle?.setAttribute('aria-expanded','false')}});
