icons.phone='<path d="m7 3 3 5-3 3q2 4 6 6l3-3 5 3-1 4C10 23 1 14 3 4Z"/>';
const callChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('daily-calls'):null;
let activeCall=null;const incomingCalls=new Map();let callFrame;
function callSignal(type,data={}){callChannel?.postMessage({type,actorId,callId:activeCall?.id,sourceId:activeCall?.sourceId,...data})}
function callStateView(){const invite=incomingCalls.get(selectedSource),call=activeCall?.sourceId===selectedSource?activeCall:null;if(!call&&!invite)return '';if(!call)return `<div class="call-invite"><span>${esc(authorName(invite.actorId))} wants to call</span><div><button class="btn" id="decline-call">Decline</button><button class="btn" id="join-preview">Preview</button></div></div>`;return `<div class="call-panel"><div class="call-panel-head"><span>${call.phase==='live'?'In call':call.phase==='connecting'?'Connecting':'Call preview'}</span><button id="leave-call" aria-label="${call.phase==='live'?'End call':'Cancel call'}">${icon('close')}</button></div><div class="call-preview-people"><div><span class="call-avatar">${esc(authorName(actorId).slice(0,1))}</span><span>You</span><small>${call.localReady?'Ready':'Not ready'}</small></div><div><span class="call-avatar">${esc(authorName(actorId==='self'?'member-maya':'self').slice(0,1))}</span><span>${esc(authorName(actorId==='self'?'member-maya':'self'))}</span><small>${call.remoteReady?'Ready':'Not ready'}</small></div></div><canvas id="call-visualizer" aria-label="Microphone level preview" role="img" width="640" height="60"></canvas><div class="call-panel-footer"><span role="status">${esc(call.error|| (call.loading?'Requesting microphone':call.phase==='live'?'Connected':call.phase==='connecting'?'Connecting audio':call.localReady?'Waiting for the other person':'Check your microphone'))}</span>${call.phase==='preview'?`<button class="btn ${call.localReady?'':'primary'}" id="ready-call" ${!call.stream||call.loading?'disabled':''}>${call.localReady?'Not ready':'Ready'}</button>`:`<button class="btn" id="end-call">End call</button>`}${!call.stream&&!call.loading?'<button class="btn" id="retry-mic">Enable microphone</button>':''}</div></div>`}
function updateCallUI(){const root=document.querySelector('#call-space');if(root){root.innerHTML=callStateView();bindCallPanel()}updateCallReturn()}
function updateCallReturn(){let root=document.querySelector('#active-call-return');if(!root){root=document.createElement('div');root.id='active-call-return';document.querySelector('.sidebar-bottom')?.prepend(root)}if(!root)return;root.innerHTML=activeCall?`<button id="return-call">${icon('phone')} ${activeCall.phase==='live'?'Call in progress':'Call preview'}</button><button id="quick-end-call" aria-label="End call">${icon('close')}</button>`:'';root.querySelector('#return-call')?.addEventListener('click',()=>{selectedSource=activeCall.sourceId;go('Source');sourceMode='Messages';render()});root.querySelector('#quick-end-call')?.addEventListener('click',()=>endCall(true))}
function bindCalls(){document.querySelector('#start-call')?.addEventListener('click',()=>{if(activeCall){selectedSource=activeCall.sourceId;go('Source');sourceMode='Messages';render();return}beginCall()});bindCallPanel();updateCallReturn();callSignal('hello')}
function bindCallPanel(){cancelAnimationFrame(callFrame);document.querySelector('#ready-call')?.addEventListener('click',()=>{const c=activeCall;if(!c?.stream||c.phase!=='preview')return;c.localReady=!c.localReady;callSignal('ready',{ready:c.localReady});updateCallUI();maybeConnect()});document.querySelector('#retry-mic')?.addEventListener('click',prepareCallMic);document.querySelector('#leave-call')?.addEventListener('click',()=>endCall(true));document.querySelector('#end-call')?.addEventListener('click',()=>endCall(true));document.querySelector('#join-preview')?.addEventListener('click',()=>beginCall(incomingCalls.get(selectedSource)));document.querySelector('#decline-call')?.addEventListener('click',()=>{const invite=incomingCalls.get(selectedSource);callSignal('end',{callId:invite.callId,sourceId:selectedSource});incomingCalls.delete(selectedSource);updateCallUI()});drawCallVisualizer()}
async function beginCall(invite){if(activeCall)return;if(!callChannel||!window.RTCPeerConnection){toast('Calls unavailable in this browser');return}activeCall={id:invite?.callId||crypto.randomUUID(),sourceId:selectedSource,caller:!invite,localReady:false,remoteReady:invite?.remoteReady||false,phase:'preview',stream:null,context:null,pc:null,candidates:[],loading:false};incomingCalls.delete(selectedSource);sourceMode='Messages';render();if(!invite)callSignal('invite');else callSignal('joined');await prepareCallMic()}
async function prepareCallMic(){const c=activeCall;if(!c||c.loading||c.stream)return;c.loading=true;c.error='';updateCallUI();try{if(!navigator.mediaDevices?.getUserMedia)throw Error('unsupported');const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(activeCall!==c){stream.getTracks().forEach(t=>t.stop());return}c.stream=stream;stream.getAudioTracks().forEach(t=>t.enabled=!mediaControls.muted);c.context=new AudioContext();await c.context.resume();c.analyser=c.context.createAnalyser();c.analyser.fftSize=256;c.context.createMediaStreamSource(stream).connect(c.analyser);stream.getAudioTracks()[0].onended=()=>{if(activeCall===c)endCall(true,'Microphone disconnected')}}catch(e){c.error=e.name==='NotAllowedError'?'Allow microphone access to get ready':e.name==='NotFoundError'?'No microphone found':'Microphone unavailable'}finally{if(activeCall===c){c.loading=false;updateCallUI()}}}
function drawCallVisualizer(){const canvas=document.querySelector('#call-visualizer'),c=activeCall;if(!canvas)return;const ctx=canvas.getContext('2d'),data=new Uint8Array(c?.analyser?.frequencyBinCount||128);const draw=()=>{if(!canvas.isConnected||activeCall!==c)return;ctx.clearRect(0,0,canvas.width,canvas.height);if(c?.analyser)c.analyser.getByteFrequencyData(data);ctx.fillStyle='#aaa';for(let i=0;i<48;i++){const value=data[Math.floor(i*data.length/48)]||0,height=Math.max(3,value/255*48);ctx.fillRect(i*13+4,(60-height)/2,5,height)}callFrame=requestAnimationFrame(draw)};draw()}
async function makeCallPeer(c){if(c.pc)return c.pc;const pc=new RTCPeerConnection({iceServers:[]});c.pc=pc;c.connectTimer=setTimeout(()=>{if(activeCall===c&&c.phase!=='live')endCall(true,'Audio connection unavailable')},15000);c.stream.getTracks().forEach(t=>pc.addTrack(t,c.stream));pc.onicecandidate=e=>{if(e.candidate&&activeCall===c)callSignal('ice',{candidate:e.candidate.toJSON()})};pc.ontrack=e=>{if(activeCall!==c)return;const audio=document.createElement('audio');audio.id='call-remote-audio';audio.autoplay=true;audio.muted=mediaControls.deafened;audio.srcObject=e.streams[0];document.body.append(audio);c.audio=audio;audio.play().catch(()=>{c.error='Click Resume audio';updateCallUI();const root=document.querySelector('.call-panel-footer');if(root){const button=document.createElement('button');button.className='btn';button.textContent='Resume audio';button.onclick=()=>audio.play().then(()=>{c.error='';updateCallUI()});root.append(button)}})};pc.onconnectionstatechange=()=>{if(activeCall!==c)return;if(pc.connectionState==='connected'){c.phase='live';clearTimeout(c.connectTimer);c.error='';updateCallUI()}else if(pc.connectionState==='failed'||pc.connectionState==='closed')endCall(true,'Call disconnected')};return pc}
async function maybeConnect(){const c=activeCall;if(!c?.caller||!c.localReady||!c.remoteReady||c.phase!=='preview')return;c.phase='connecting';updateCallUI();try{const pc=await makeCallPeer(c);await pc.setLocalDescription(await pc.createOffer());if(activeCall===c)callSignal('offer',{description:pc.localDescription.toJSON()})}catch{endCall(true,'Could not connect call')}}
async function flushCandidates(c){for(const candidate of c.candidates.splice(0))await c.pc.addIceCandidate(candidate)}
if(callChannel)callChannel.onmessage=async e=>{const m=e.data;if(!m||m.actorId===actorId)return;try{if(m.type==='hello'){if(activeCall?.caller)callSignal('invite');return}if(m.type==='invite'){if(activeCall){if(activeCall.id!==m.callId)callSignal('busy',{callId:m.callId,sourceId:m.sourceId});return}incomingCalls.set(m.sourceId,m);updateCallUI();return}if(m.type==='end'||m.type==='busy'){if(activeCall?.id===m.callId)endCall(false,m.type==='busy'?'The other person is in a call':'Call ended');else{incomingCalls.delete(m.sourceId);updateCallUI()}return}const c=activeCall;if(!c||c.id!==m.callId){if(m.type==='ready'&&incomingCalls.has(m.sourceId))incomingCalls.get(m.sourceId).remoteReady=m.ready;return}if(m.type==='joined'){callSignal('ready',{ready:c.localReady});return}if(m.type==='ready'){c.remoteReady=!!m.ready;updateCallUI();await maybeConnect()}else if(m.type==='offer'&&!c.caller&&c.localReady&&c.remoteReady){c.phase='connecting';updateCallUI();const pc=await makeCallPeer(c);await pc.setRemoteDescription(m.description);await flushCandidates(c);await pc.setLocalDescription(await pc.createAnswer());callSignal('answer',{description:pc.localDescription.toJSON()})}else if(m.type==='answer'&&c.caller&&c.pc){await c.pc.setRemoteDescription(m.description);await flushCandidates(c)}else if(m.type==='ice'){if(c.pc?.remoteDescription)await c.pc.addIceCandidate(m.candidate);else c.candidates.push(m.candidate)}}catch{endCall(true,'Could not connect call')}};
function endCall(notify=false,reason=''){const c=activeCall;if(!c)return;if(notify)callSignal('end');activeCall=null;clearTimeout(c.connectTimer);cancelAnimationFrame(callFrame);c.pc?.close();c.stream?.getTracks().forEach(t=>{t.onended=null;t.stop()});c.context?.close().catch(()=>{});c.audio?.remove();updateCallUI();if(reason)toast(reason)}
window.addEventListener('pagehide',()=>endCall(true));window.addEventListener('offline',()=>endCall(true,'Call disconnected'));

function sourceRow(s){return `<article class="source-card" draggable="${page==='Sources'}" data-draggable-source="${esc(s.id)}"><button class="source-open" data-open-source="${esc(s.id)}"><span class="source-tile">${esc(s.initial)}</span><span class="source-row-name">${esc(s.name)}${s.matrixNetwork?`<small>${esc(s.matrixNetwork)}</small>`:''}${tagChips(s)}</span></button>${(s.member||s.matrixChatId)&&s.id!=='self'?`<button class="message-source" data-message-source="${esc(s.id)}" aria-label="Message ${esc(s.name)}" title="Message ${esc(s.name)}">${icon('message')}</button>`:''}${!s.saved?`<button class="btn" data-follow="${esc(s.id)}">${icon('plus')} Add</button>`:''}<details class="source-row-menu"><summary aria-label="Options for ${esc(s.name)}" title="Options for ${esc(s.name)}">${icon('more')}</summary><div class="source-menu-actions" role="group" aria-label="Options for ${esc(s.name)}"><button data-source="${esc(s.id)}">${icon('sources')} About & links</button><button data-tag-source="${esc(s.id)}">${icon('tag')} Tags</button>${page==='Sources'&&categories.length?`<button data-move-source="${esc(s.id)}">${icon('folder')} Move to category</button>`:''}</div></details></article>`}

function categoryDescendants(id){const result=new Set(),stack=[id];while(stack.length){const current=stack.pop();if(result.has(current))continue;result.add(current);for(const c of categories)if(c.parentId===current)stack.push(c.id)}return result}
function categoryPath(c){const names=[],seen=new Set();while(c&&!seen.has(c.id)){seen.add(c.id);names.unshift(c.name);c=categories.find(p=>p.id===c.parentId)}return names.join(' / ')}
function categoryOptions(exclude=null){const blocked=exclude?categoryDescendants(exclude):new Set();return categories.filter(c=>!blocked.has(c.id)).map(c=>`<option value="${c.id}">${esc(categoryPath(c))}</option>`).join('')}
function categoryTree(list){if(!categories.length)return `<div class="source-grid">${list.map(sourceRow).join('')}</div>${!list.length?'<div class="empty">No sources</div>':''}`;const valid=new Set(categories.map(c=>c.id)),children=new Map(),byCategory=new Map();for(const c of categories){const parent=valid.has(c.parentId)?c.parentId:null;if(!children.has(parent))children.set(parent,[]);children.get(parent).push(c)}for(const s of list){const key=valid.has(s.categoryId)?s.categoryId:null;if(!byCategory.has(key))byCategory.set(key,[]);byCategory.get(key).push(s)}let html='<div class="source-categories">';const stack=(children.get(null)||[]).slice().reverse().map(c=>({c,depth:0})),seen=new Set();while(stack.length){const {c,depth}=stack.pop();if(seen.has(c.id))continue;seen.add(c.id);html+=`<section class="source-category" style="--category-depth:${Math.min(depth,4)}"><div class="category-heading" data-drop-category="${c.id}"><button class="category-collapse" data-collapse-category="${c.id}" aria-expanded="${!c.collapsed}" aria-label="${c.collapsed?'Expand':'Collapse'} ${esc(c.name)}"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${c.collapsed?'m9 6 6 6-6 6':'m6 9 6 6 6-6'}"/></svg><span>${esc(c.name)}</span></button>${tagChips(c)}<div class="category-actions"><button data-tag-category="${c.id}" aria-label="Tags for ${esc(c.name)} category" title="Tags">${icon('tag')}</button><button data-add-child="${c.id}" aria-label="Add subcategory to ${esc(c.name)}" title="Add subcategory">${icon('plus')}</button><button data-edit-category="${c.id}" aria-label="Edit ${esc(c.name)} category" title="Edit category">${icon('more')}</button></div></div>${!c.collapsed?`<div class="source-grid category-sources">${(byCategory.get(c.id)||[]).map(sourceRow).join('')}</div>`:''}</section>`;if(!c.collapsed)for(const child of (children.get(c.id)||[]).slice().reverse())stack.push({c:child,depth:depth+1})}const uncategorized=byCategory.get(null)||[];html+=`<section class="uncategorized-sources ${uncategorized.length?'':'empty-category-drop'}"><div class="category-heading" data-drop-category=""><span>Uncategorized</span></div><div class="source-grid">${uncategorized.map(sourceRow).join('')}</div></section></div>`;return html}
function categoryEditor(id=null,parentId=null){const category=categories.find(c=>c.id===id);modal(category?'Edit category':'Create category',`<form id="category-form"><label class="category-field">Name<input type="text" id="category-name" required value="${esc(category?.name||'')}" autocomplete="off"></label><label class="category-field">Parent category<select id="category-parent"><option value="">None</option>${categoryOptions(id)}</select></label><div class="category-form-actions">${category?'<button type="button" id="delete-category">Delete category</button>':''}<button type="submit" class="btn">${category?'Save':'Create'}</button></div></form>`);document.querySelector('#category-parent').value=category?.parentId||parentId||'';document.querySelector('#category-name').focus();document.querySelector('#category-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#category-name').value.trim(),parent=document.querySelector('#category-parent').value||null;if(!name)return;if(id&&categoryDescendants(id).has(parent))return toast('A category cannot contain itself');if(category){category.name=name;category.parentId=parent}else categories.push({id:crypto.randomUUID(),name,parentId:parent,collapsed:false});if(parent){const p=categories.find(c=>c.id===parent);if(p)p.collapsed=false}persist();document.querySelector('#modal').close();render()};document.querySelector('#delete-category')?.addEventListener('click',()=>{for(const s of sources)if(s.categoryId===id)s.categoryId=category.parentId;for(const c of categories)if(c.parentId===id)c.parentId=category.parentId;categories=categories.filter(c=>c.id!==id);persist();document.querySelector('#modal').close();render()})}
function moveSource(id){const s=sources.find(s=>s.id===id);modal('Move '+esc(s.name),`<form id="move-source-form"><label class="category-field">Category<select id="source-category"><option value="">Uncategorized</option>${categoryOptions()}</select></label><button class="btn full" type="submit">Move</button></form>`);document.querySelector('#source-category').value=s.categoryId||'';document.querySelector('#move-source-form').onsubmit=e=>{e.preventDefault();s.categoryId=document.querySelector('#source-category').value||null;persist();document.querySelector('#modal').close();render()}}
function bindCategories(){document.querySelector('#add-category')?.addEventListener('click',()=>categoryEditor());document.querySelectorAll('[data-add-child]').forEach(b=>b.onclick=()=>categoryEditor(null,b.dataset.addChild));document.querySelectorAll('[data-edit-category]').forEach(b=>b.onclick=()=>categoryEditor(b.dataset.editCategory));document.querySelectorAll('[data-collapse-category]').forEach(b=>b.onclick=()=>{const c=categories.find(c=>c.id===b.dataset.collapseCategory);c.collapsed=!c.collapsed;persist();render();document.querySelector(`[data-collapse-category="${c.id}"]`)?.focus()});document.querySelectorAll('[data-move-source]').forEach(b=>b.onclick=()=>moveSource(b.dataset.moveSource));document.querySelectorAll('[data-draggable-source]').forEach(row=>row.ondragend=()=>document.body.classList.remove('is-source-dragging'));document.querySelectorAll('[data-draggable-source]').forEach(row=>row.ondragstart=e=>{document.body.classList.add('is-source-dragging');e.dataTransfer.setData('application/x-source-id',row.dataset.draggableSource);e.dataTransfer.effectAllowed='move'});document.querySelectorAll('[data-drop-category]').forEach(target=>{target.ondragover=e=>{if(e.dataTransfer.types.includes('application/x-source-id')){e.preventDefault();target.classList.add('category-drop-target')}};target.ondragleave=()=>target.classList.remove('category-drop-target');target.ondrop=e=>{e.preventDefault();const s=sources.find(s=>s.id===e.dataTransfer.getData('application/x-source-id'));if(s){s.categoryId=target.dataset.dropCategory||null;persist();render()}target.classList.remove('category-drop-target')}})}

let publishingDraft={type:'post',text:typeof postDraft==='string'?postDraft:'',title:'',description:'',attachments:[],question:'',options:['',''],schedule:'',openSource:false,license:'',items:[],...stored.publishingDraft},uploadingPostFiles=0,streamPreview=null;
function savePublishingDraft(){postDraft=publishingDraft.text;persist()}
function stopStreamPreview(){streamPreview?.getTracks().forEach(t=>t.stop());streamPreview=null;const video=document.querySelector('#stream-preview');if(video){video.srcObject=null;video.hidden=true}const b=document.querySelector('#preview-stream');if(b)b.textContent='Preview'}
function scheduleISO(value){if(!value)return null;const parts=value.split(/[-T:]/).map(Number),[y,m,d,h,min]=parts;const wanted=Date.UTC(y,m-1,d,h,min);let guess=wanted;const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:profile.timezone||'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});for(let i=0;i<3;i++){const p=Object.fromEntries(formatter.formatToParts(new Date(guess)).map(p=>[p.type,p.value]));const actual=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);guess+=wanted-actual}const check=Object.fromEntries(formatter.formatToParts(new Date(guess)).map(p=>[p.type,p.value]));if(+check.year!==y||+check.month!==m||+check.day!==d||+check.hour!==h||+check.minute!==min)throw Error('This time does not exist in your timezone');return new Date(guess).toISOString()}
function ensureOwnSource(){let s=sources.find(s=>s.id==='self');if(!s){s={id:'self',name:profile.name,initial:profile.name.slice(0,1),color:'#ddd',type:'Person',bio:'',links:['App'],saved:true,member:true,username:profile.username};sources.push(s)}s.name=profile.name;s.username=profile.username;return s}
function postComposer(){stopStreamPreview();const d=publishingDraft;modal('Post',`<form id="post-form" class="publishing-form"><div class="post-author"><span class="avatar">${esc(profile.name.slice(0,1))}</span><span>${esc(profile.name)}${settings.showUsername?`<small>@${esc(profile.username)}</small>`:''}</span></div><div class="publish-types" role="tablist" aria-label="Post type">${[['post','Post'],['poll','Poll'],['live','Live']].map(([v,l])=>`<button type="button" role="tab" aria-selected="${d.type===v}" data-publish-type="${v}">${l}</button>`).join('')}</div>${d.type==='live'?`<div class="stream-setup"><select id="stream-source" aria-label="Stream source"><option value="camera">Camera</option><option value="screen">Screen</option></select><button type="button" class="btn" id="preview-stream">Preview</button><video id="stream-preview" autoplay playsinline muted hidden></video><p class="publish-note">Streaming service not connected</p></div>`:d.type==='poll'?`<div class="poll-editor"><input type="text" id="poll-question" aria-label="Poll question" placeholder="Question" value="${esc(d.question)}"><div id="poll-options">${pollOptionInputs()}</div><button type="button" class="text-action" id="add-poll-option">${icon('plus')} Add option</button></div>`:''}<textarea id="post-content" aria-label="Post content" placeholder="${d.type==='post'?'Write a post':d.type==='poll'?'Add context (optional)':'Stream announcement (optional)'}" rows="${d.type==='post'?4:2}">${esc(d.text)}</textarea><div id="post-cultural-draft"></div><div id="post-attachment-list"></div><div class="publish-tools"><button type="button" id="post-add-item" class="btn">${icon('sources')} Item</button><button type="button" id="post-attach" class="btn">${icon('plus')} Files</button><input type="file" id="post-file-input" multiple hidden><button type="button" id="post-schedule-toggle" class="btn" aria-expanded="${!!d.schedule}" aria-controls="post-schedule-panel">${icon('clock')} Schedule</button></div><div id="post-schedule-panel" ${d.schedule?'':'hidden'}><label>Publish time · ${esc(profile.timezone)}<input type="datetime-local" id="post-schedule" aria-label="Publish time" value="${esc(d.schedule)}"></label><button type="button" class="text-action" id="clear-schedule">Clear</button><span class="publish-note">Publishes while this app is open</span></div>${openSourceComposer()}<details class="post-optional" ${d.title||d.description?'open':''}><summary>Title & description <span>optional</span></summary><input type="text" id="post-title" aria-label="Post title (optional)" placeholder="Title" value="${esc(d.title)}"><textarea id="post-description" aria-label="Post description (optional)" placeholder="Description" rows="2">${esc(d.description)}</textarea></details><div class="post-compose-actions"><span id="post-upload-status" role="status"></span><button class="btn primary" id="publish-post" type="submit">${d.schedule?'Schedule':d.type==='live'?'Go live':'Post'}</button></div></form>`);document.querySelector('#modal').classList.add('publishing-dialog');document.querySelector('#modal').addEventListener('close',()=>{stopStreamPreview();document.querySelector('#modal').classList.remove('publishing-dialog')},{once:true});bindPublishing();drawCulturalDraft();drawPostAttachments();validatePostButton()}
function pollOptionInputs(){return publishingDraft.options.map((value,i)=>`<div class="poll-option-input"><input type="text" data-poll-option="${i}" aria-label="Poll option ${i+1}" placeholder="Option ${i+1}" value="${esc(value)}"><button type="button" data-remove-option="${i}" aria-label="Remove option ${i+1}" ${publishingDraft.options.length<=2?'disabled':''}>${icon('close')}</button></div>`).join('')}
function bindPollInputs(){document.querySelectorAll('[data-poll-option]').forEach(el=>el.oninput=()=>{publishingDraft.options[+el.dataset.pollOption]=el.value;savePublishingDraft();validatePostButton()});document.querySelectorAll('[data-remove-option]').forEach(el=>el.onclick=()=>{publishingDraft.options.splice(+el.dataset.removeOption,1);savePublishingDraft();document.querySelector('#poll-options').innerHTML=pollOptionInputs();bindPollInputs();validatePostButton()})}
function validatePostButton(){const d=publishingDraft,b=document.querySelector('#publish-post');if(!b)return;const has=d.text.trim()||d.title.trim()||d.description.trim()||d.attachments.length||d.items?.length;b.disabled=!!uploadingPostFiles||!!(d.openSource&&(!d.license||!d.attachments.length))||(d.type==='poll'?(!d.question.trim()||d.options.some(o=>!o.trim())||d.options.length<2):d.type==='live'?!d.schedule:!has);b.textContent=d.schedule?'Schedule':d.type==='live'?'Go live':'Post';document.querySelector('#post-upload-status').textContent=uploadingPostFiles?'Adding files…':''}
async function addPostFiles(files){uploadingPostFiles+=files.length;validatePostButton();for(const file of files){try{const a={id:crypto.randomUUID(),name:file.name,type:file.type||'application/octet-stream',size:file.size,kind:'file'};await storeMedia(a.id,file);publishingDraft.attachments.push(a);savePublishingDraft()}catch(e){toast(e.name==='QuotaExceededError'?'Device storage is full. File not added.':'Could not add file')}finally{uploadingPostFiles--;if(document.querySelector('#post-attachment-list'))drawPostAttachments();validatePostButton()}}}
function drawPostAttachments(){const root=document.querySelector('#post-attachment-list');if(!root)return;root.innerHTML=publishingDraft.attachments.map((a,i)=>`<div class="post-file-draft">${attachmentView(a)}<button type="button" data-remove-post-file="${i}" aria-label="Remove ${esc(a.name)}">${icon('close')}</button></div>`).join('');root.querySelectorAll('[data-remove-post-file]').forEach(b=>b.onclick=()=>{publishingDraft.attachments.splice(+b.dataset.removePostFile,1);savePublishingDraft();drawPostAttachments();validatePostButton()});hydrateMedia(root)}
function bindPublishing(){document.querySelector('#post-add-item').onclick=itemPicker;document.querySelector('#post-open-source').onchange=e=>{publishingDraft.openSource=e.target.checked;document.querySelector('#post-license-panel').hidden=!e.target.checked;savePublishingDraft();validatePostButton()};document.querySelector('#post-license').onchange=e=>{publishingDraft.license=e.target.value;savePublishingDraft();validatePostButton()};for(const [id,key] of [['post-content','text'],['post-title','title'],['post-description','description'],['poll-question','question'],['post-schedule','schedule']]){const el=document.getElementById(id);if(el)el.oninput=()=>{publishingDraft[key]=el.value;savePublishingDraft();validatePostButton()}}document.querySelectorAll('[data-publish-type]').forEach(b=>b.onclick=()=>{publishingDraft.type=b.dataset.publishType;savePublishingDraft();stopStreamPreview();postComposer()});bindPollInputs();document.querySelector('#add-poll-option')?.addEventListener('click',()=>{publishingDraft.options.push('');savePublishingDraft();document.querySelector('#poll-options').innerHTML=pollOptionInputs();bindPollInputs();document.querySelector('[data-poll-option]:last-of-type')?.focus();validatePostButton()});document.querySelector('#post-attach').onclick=()=>document.querySelector('#post-file-input').click();document.querySelector('#post-file-input').onchange=e=>{addPostFiles([...e.target.files]);e.target.value=''};document.querySelector('#post-schedule-toggle').onclick=e=>{const panel=document.querySelector('#post-schedule-panel');panel.hidden=!panel.hidden;e.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)document.querySelector('#post-schedule').focus()};document.querySelector('#clear-schedule').onclick=()=>{publishingDraft.schedule='';document.querySelector('#post-schedule').value='';savePublishingDraft();validatePostButton()};document.querySelector('#preview-stream')?.addEventListener('click',async()=>{if(streamPreview){stopStreamPreview();return}const button=document.querySelector('#preview-stream');button.disabled=true;try{const type=document.querySelector('#stream-source').value,stream=type==='screen'?await navigator.mediaDevices.getDisplayMedia({video:true,audio:true}):await navigator.mediaDevices.getUserMedia({video:true,audio:true});const video=document.querySelector('#stream-preview');if(!video){stream.getTracks().forEach(t=>t.stop());return}streamPreview=stream;video.srcObject=stream;video.hidden=false;button.textContent='Stop preview';stream.getVideoTracks()[0].onended=stopStreamPreview}catch(e){toast(e.name==='NotAllowedError'?'Preview permission was not granted':'Preview unavailable')}finally{if(button.isConnected)button.disabled=false}});document.querySelector('#stream-source')?.addEventListener('change',stopStreamPreview);const form=document.querySelector('#post-form');form.ondragover=e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()};form.ondrop=e=>{e.preventDefault();addPostFiles([...e.dataTransfer.files])};form.onsubmit=e=>{e.preventDefault();submitPublication()}}
function submitPublication(){if(document.querySelector('#publish-post').disabled)return;const d=publishingDraft;let publishAt=null;try{publishAt=scheduleISO(d.schedule);if(publishAt&&new Date(publishAt)<=new Date())throw Error('Choose a future publish time')}catch(e){toast(e.message||'Invalid publish time');return}if(d.type==='live'&&!publishAt){toast('Streaming service not connected');return}ensureOwnSource();const post={id:Date.now(),source:'self',platform:'App',time:'Just now',title:d.title.trim(),text:d.text.trim(),description:d.description.trim(),attachments:d.attachments.slice(),items:(d.items||[]).slice(),openSource:!!d.openSource,license:d.openSource?d.license:null,contributions:[],type:d.type,status:publishAt?'scheduled':'published',publishAt,createdAt:new Date().toISOString()};if(d.type==='poll'){const options=d.options.map(o=>o.trim());if(new Set(options.map(o=>o.toLocaleLowerCase())).size!==options.length){toast('Poll options must be different');return}post.poll={question:d.question.trim(),options,vote:null}}ownPosts.unshift(post);if(!publishAt)posts.unshift(post);publishingDraft={type:'post',text:'',title:'',description:'',attachments:[],question:'',options:['',''],schedule:''};postDraft='';persist();document.querySelector('#modal').close();selectedSource='self';go('Source');sourceMode=publishAt?'Scheduled':'Updates';render();toast(publishAt?'Scheduled':'Posted')}
function publishDuePosts(){if(window.NavRestoring)return;const now=Date.now();let changed=false;for(const p of ownPosts){if(p.status==='scheduled'&&new Date(p.publishAt).getTime()<=now){p.status='published';p.time='Just now';if(!posts.some(x=>x.id===p.id))posts.unshift(p);changed=true}}if(changed){persist();if(page==='Source'&&selectedSource==='self'&&sourceMode==='Scheduled')render()}}
function scheduledPostsView(){const list=ownPosts.filter(p=>p.status==='scheduled').sort((a,b)=>new Date(a.publishAt)-new Date(b.publishAt));return `<div class="scheduled-posts">${list.map(p=>`<details class="scheduled-item"><summary>${p.type==='live'?'Stream announcement':p.type==='poll'?'Poll':'Post'}<time>${esc(messageTime(p.publishAt))}</time></summary><div>${p.title?`<h3>${esc(p.title)}</h3>`:''}${p.text?`<p>${esc(p.text)}</p>`:''}${p.poll?`<p>${esc(p.poll.question)}</p>`:''}<button class="btn" data-reschedule="${p.id}">Reschedule</button></div></details>`).join('')||'<div class="empty">No scheduled posts</div>'}</div>`}
function pollMarkup(p){return p.poll?`<section class="post-poll"><h3>${esc(p.poll.question)}</h3>${p.poll.options.map((o,i)=>`<button type="button" data-poll-vote="${p.id}" data-vote-index="${i}" aria-pressed="${p.poll.vote===i}"><span>${esc(o)}</span>${p.poll.vote===i?icon('check'):''}</button>`).join('')}</section>`:''}
function bindPublicationView(root){bindArtworkFallback(root);root.querySelectorAll('[data-contribute-post]').forEach(b=>b.onclick=()=>contributePost(+b.dataset.contributePost));hydrateMedia(root);root.querySelectorAll('[data-post-media]').forEach(async el=>{try{el.src=await mediaUrl(el.dataset.postMedia)}catch{el.hidden=true}});root.querySelectorAll('[data-poll-vote]').forEach(b=>b.onclick=()=>{const p=ownPosts.find(p=>p.id===+b.dataset.pollVote);p.poll.vote=p.poll.vote===+b.dataset.voteIndex?null:+b.dataset.voteIndex;persist();const poll=root.querySelector('.post-poll');poll.outerHTML=pollMarkup(p);bindPublicationView(root)});document.querySelectorAll('[data-reschedule]').forEach(b=>b.onclick=()=>{const p=ownPosts.find(p=>p.id===+b.dataset.reschedule);modal('Reschedule',`<form id="reschedule-form"><label class="category-field">Publish time · ${esc(profile.timezone)}<input type="datetime-local" id="reschedule-time" required></label><button class="btn full">Save</button></form>`);document.querySelector('#reschedule-form').onsubmit=e=>{e.preventDefault();try{const date=scheduleISO(document.querySelector('#reschedule-time').value);if(new Date(date)<=new Date())throw Error('Choose a future publish time');p.publishAt=date;persist();document.querySelector('#modal').close();render()}catch(e){toast(e.message)}}})}
setInterval(publishDuePosts,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)publishDuePosts()});

function openSourceComposer(){const d=publishingDraft;return `<div class="open-source-composer"><label class="open-source-toggle"><input type="checkbox" id="post-open-source" ${d.openSource?'checked':''}>Open source</label><div id="post-license-panel" ${d.openSource?'':'hidden'}><label>License<select id="post-license" aria-label="Post license"><option value="">Choose a license</option>${['CC0 1.0','CC BY 4.0','MIT','Apache 2.0'].map(l=>`<option ${d.license===l?'selected':''}>${l}</option>`).join('')}</select></label></div></div>`}
function openSourcePost(p){if(!p.openSource)return '';return `<section class="open-source-post"><div><span>Open source</span><span class="post-license-label">${esc(p.license)}</span><button class="btn" data-contribute-post="${p.id}">${icon('plus')} Contribute files</button></div>${p.contributions?.length?`<details class="contribution-list"><summary>Contributions · ${p.contributions.length}</summary>${p.contributions.map(c=>`<article><header><strong>${esc(authorName(c.author))}</strong><time>${esc(messageTime(c.time))}</time><span>${c.status||'Submitted'}</span></header>${c.text?`<p>${esc(c.text)}</p>`:''}<div>${c.attachments.map(attachmentView).join('')}</div></article>`).join('')}</details>`:''}</section>`}
function contributePost(id){const p=ownPosts.find(p=>p.id===id);let files=[],busy=0;modal('Contribute files',`<form id="contribute-form"><textarea id="contribute-text" placeholder="Note (optional)" aria-label="Contribution note" rows="3"></textarea><input type="file" id="contribute-files" multiple hidden><button type="button" class="btn" id="choose-contribution">${icon('plus')} Files</button><div id="contribution-files"></div><div class="post-compose-actions"><span>${esc(p.license)}</span><button class="btn primary" id="submit-contribution" disabled>Submit</button></div></form>`);document.querySelector('#choose-contribution').onclick=()=>document.querySelector('#contribute-files').click();document.querySelector('#contribute-files').onchange=async e=>{const list=[...e.target.files];busy+=list.length;document.querySelector('#submit-contribution').disabled=true;for(const f of list){try{const a={id:crypto.randomUUID(),kind:'file',name:f.name,type:f.type||'application/octet-stream',size:f.size};await storeMedia(a.id,f);files.push(a)}catch{toast('Could not add file')}finally{busy--}}const root=document.querySelector('#contribution-files');if(root){root.innerHTML=files.map(attachmentView).join('');hydrateMedia(root);document.querySelector('#submit-contribution').disabled=busy>0||!files.length}};document.querySelector('#contribute-form').onsubmit=e=>{e.preventDefault();if(busy||!files.length)return;(p.contributions||=[]).push({id:crypto.randomUUID(),author:actorId,time:new Date().toISOString(),text:document.querySelector('#contribute-text').value.trim(),attachments:files,status:'Submitted'});persist();document.querySelector('#modal').close();const target=document.querySelector(`[data-post="${p.id}"] .update-content`);if(target){render();const item=document.querySelector(`[data-post="${p.id}"]`);if(item)item.open=true}toast('Contribution submitted')}}

icons.tag='<path d="M3 3h8l10 10-8 8L3 11Z"/><circle cx="7.5" cy="7.5" r="1"/>';
const tagColor=t=>/^#[0-9a-f]{6}$/i.test(t.color)?t.color:'#cccccc';
function tagInk(hex){const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.179?'#111111':'#ffffff'}
function entityTags(entity){return (entity.tagIds||[]).map(id=>tags.find(t=>t.id===id)).filter(Boolean)}
function tagChips(entity){return `<span class="tag-chips">${entityTags(entity).map(t=>`<span class="custom-tag" style="background:${tagColor(t)};color:${tagInk(tagColor(t))}">${esc(t.name)}</span>`).join('')}</span>`}
function tagTarget(type,id){return (type==='category'?categories:sources).find(e=>e.id===id)}
function tagManager(type,id){const entity=tagTarget(type,id);if(!entity)return;modal('Tags',`<p class="tag-target-name">${esc(entity.name)}</p><div class="tag-picker-list">${tags.map(t=>`<div class="tag-picker-row"><label><input type="checkbox" data-apply-tag="${t.id}" ${(entity.tagIds||[]).includes(t.id)?'checked':''}><span class="custom-tag" style="background:${tagColor(t)};color:${tagInk(tagColor(t))}">${esc(t.name)}</span></label><button type="button" data-edit-tag="${t.id}" aria-label="Edit ${esc(t.name)} tag" title="Edit tag">${icon('edit')}</button></div>`).join('')}</div><button class="btn full" id="create-tag">${icon('plus')} New tag</button>`);document.querySelectorAll('[data-apply-tag]').forEach(el=>el.onchange=()=>{const ids=new Set(entity.tagIds||[]);el.checked?ids.add(el.dataset.applyTag):ids.delete(el.dataset.applyTag);entity.tagIds=[...ids];persist();render()});document.querySelectorAll('[data-edit-tag]').forEach(el=>el.onclick=()=>editTag(type,id,el.dataset.editTag));document.querySelector('#create-tag').onclick=()=>editTag(type,id)}
function editTag(type,targetId,id=null){const tag=tags.find(t=>t.id===id),entity=tagTarget(type,targetId);let color=tag?tagColor(tag):'#b1c3d9';modal(tag?'Edit tag':'New tag',`<form id="tag-editor"><label class="category-field">Name<input type="text" id="tag-name" value="${esc(tag?.name||'')}" required autocomplete="off"></label><div class="tag-color-field"><label for="tag-color">Color</label><input type="color" id="tag-color" value="${color}"><input type="text" id="tag-color-hex" aria-label="Tag hex color" value="${color}" pattern="#[a-fA-F0-9]{6}" required></div><div id="tag-preview">${tagChips({tagIds:tag?[tag.id]:[]})}</div><div class="category-form-actions">${tag?'<button type="button" id="delete-tag">Delete tag</button>':'<button type="button" id="cancel-tag">Cancel</button>'}<button type="submit" class="btn">${tag?'Save':'Create & apply'}</button></div></form>`);const name=document.querySelector('#tag-name'),picker=document.querySelector('#tag-color'),hex=document.querySelector('#tag-color-hex');const preview=()=>{const value=/^#[a-f0-9]{6}$/i.test(hex.value)?hex.value:color;document.querySelector('#tag-preview').innerHTML=`<span class="custom-tag" style="background:${value};color:${tagInk(value)}">${esc(name.value||'Tag')}</span>`};name.oninput=preview;picker.oninput=()=>{color=picker.value;hex.value=color;preview()};hex.oninput=()=>{if(/^#[a-f0-9]{6}$/i.test(hex.value)){color=hex.value;picker.value=color}preview()};preview();name.focus();document.querySelector('#cancel-tag')?.addEventListener('click',()=>tagManager(type,targetId));document.querySelector('#tag-editor').onsubmit=e=>{e.preventDefault();const text=name.value.trim();if(!text)return;if(tag){tag.name=text;tag.color=hex.value}else{const created={id:crypto.randomUUID(),name:text,color:hex.value};tags.push(created);entity.tagIds=[...new Set([...(entity.tagIds||[]),created.id])]}persist();render();tagManager(type,targetId)};document.querySelector('#delete-tag')?.addEventListener('click',()=>{tags=tags.filter(t=>t.id!==id);for(const e of [...sources,...categories])e.tagIds=(e.tagIds||[]).filter(t=>t!==id);persist();render();tagManager(type,targetId)})}
function bindTags(){document.querySelectorAll('[data-tag-source]').forEach(b=>b.onclick=()=>tagManager('source',b.dataset.tagSource));document.querySelectorAll('[data-tag-category]').forEach(b=>b.onclick=()=>tagManager('category',b.dataset.tagCategory))}

const itemKinds={game:'Game',show:'Show',film:'Film',book:'Book',album:'Album',artist:'Artist',song:'Song',other:'Other'};let catalogAbort=null;
function culturalCard(item,removable=false,index=0){const initial=item.title.slice(0,1).toUpperCase();return `<article class="cultural-card"><div class="cultural-art object-stage object-${Object.hasOwn(itemKinds,item.kind)?item.kind:'other'}" role="img" aria-label="${esc(itemKinds[item.kind]||'Item')} artwork for ${esc(item.title)}"><div class="media-object" aria-hidden="true">${item.kind==='album'?'<div class="object-record"></div>':''}<div class="object-back"></div><div class="object-spine"></div><div class="object-edge"></div><div class="object-top"></div><div class="object-front">${item.image?`<img src="${esc(item.image)}" alt="${esc(item.title)} artwork" loading="lazy" referrerpolicy="no-referrer">`:`<span>${esc(initial)}</span>`}</div></div></div><div class="cultural-metadata"><span class="cultural-kind">${itemKinds[item.kind]||'Item'}${item.year?' · '+esc(item.year):''}</span><h3>${esc(item.title)}</h3>${item.creator?`<p>${esc(item.creator)}</p>`:''}<a href="${esc(item.url)}" target="_blank" rel="noreferrer">${esc(item.provider)} ${icon('out')}</a></div>${removable?`<button class="remove-cultural-item" type="button" data-remove-cultural="${index}" aria-label="Remove ${esc(item.title)}">${icon('close')}</button>`:''}</article>`}
function postCulturalItems(p){return p.items?.length?`<div class="post-cultural-items">${p.items.map(x=>culturalCard(x)).join('')}</div>`:''}
function drawCulturalDraft(){const root=document.querySelector('#post-cultural-draft');if(!root)return;root.innerHTML=(publishingDraft.items||[]).map((x,i)=>culturalCard(x,true,i)).join('');root.querySelectorAll('[data-remove-cultural]').forEach(b=>b.onclick=()=>{publishingDraft.items.splice(+b.dataset.removeCultural,1);savePublishingDraft();drawCulturalDraft();validatePostButton()});bindArtworkFallback(root)}
function bindArtworkFallback(root){root.querySelectorAll('.cultural-art img').forEach(img=>{img.onerror=()=>{const fallback=document.createElement('span');fallback.textContent=img.alt.slice(0,1);img.replaceWith(fallback)}})}
function itemPicker(){savePublishingDraft();stopStreamPreview();modal('Add an item',`<form id="catalog-search"><select id="catalog-type" aria-label="Item type">${Object.entries(itemKinds).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select><div class="catalog-query"><input type="text" id="catalog-query" aria-label="Search database" placeholder="Search a title or name" required><button class="btn" aria-label="Search items">${icon('search')}</button></div></form><div id="catalog-status" role="status"></div><div id="catalog-results"></div><button type="button" class="text-action" id="catalog-back">Back to post</button>`);document.querySelector('#modal').classList.add('publishing-dialog');document.querySelector('#catalog-query').focus();document.querySelector('#catalog-back').onclick=()=>{catalogAbort?.abort();postComposer()};document.querySelector('#catalog-search').onsubmit=async e=>{e.preventDefault();const query=document.querySelector('#catalog-query').value.trim(),kind=document.querySelector('#catalog-type').value;if(!query)return;catalogAbort?.abort();catalogAbort=new AbortController();const status=document.querySelector('#catalog-status'),results=document.querySelector('#catalog-results');status.textContent='Searching…';results.innerHTML='';try{const response=await fetch('/api/catalog?type='+encodeURIComponent(kind)+'&q='+encodeURIComponent(query),{signal:catalogAbort.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Database unavailable');if(!results.isConnected)return;status.textContent=data.items.length?'':'No matches';results.innerHTML=data.items.map((item,i)=>`<div class="catalog-result">${culturalCard(item)}<button type="button" class="btn" data-add-cultural="${i}" ${(publishingDraft.items||[]).some(x=>x.id===item.id)?'disabled':''}>${(publishingDraft.items||[]).some(x=>x.id===item.id)?'Added':'Add'}</button></div>`).join('');bindArtworkFallback(results);results.querySelectorAll('[data-add-cultural]').forEach(b=>b.onclick=()=>{const item=data.items[+b.dataset.addCultural];publishingDraft.items||=[];if(!publishingDraft.items.some(x=>x.id===item.id))publishingDraft.items.push(item);savePublishingDraft();postComposer()})}catch(error){if(error.name!=='AbortError'&&status.isConnected)status.textContent=error.message}};document.querySelector('#catalog-type').onchange=()=>{catalogAbort?.abort();document.querySelector('#catalog-results').innerHTML='';document.querySelector('#catalog-status').textContent='';document.querySelector('#catalog-query').focus()}}

const emailState={address:'',items:[],hasMore:false,before:null,message:null};
let matrixAccounts=[],matrixSearchCursor=null;const matrixChats=new Map();
async function matrixAPI(path,options={}){const response=await fetch('/api/matrix/'+path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const data=await response.json();if(!response.ok){const error=new Error(data.error||'Matrix request failed');error.deliveryUnknown=data.deliveryUnknown;throw error}return data}
function matrixSettings(){return `<section class="matrix-settings"><h2>Messaging</h2><div class="setting-row"><span>Self-hosted bridges</span><button class="btn" id="check-matrix">Check connection</button></div><div id="matrix-connection" role="status"></div><div class="bridge-setup-actions"><button class="btn" id="browse-matrix">Choose chats</button><button class="btn" id="show-platforms" aria-expanded="false" aria-controls="messaging-platforms">Platforms</button></div><div id="messaging-platforms" hidden></div></section>`}
async function checkMatrix(){const status=document.querySelector('#matrix-connection'),button=document.querySelector('#check-matrix');button.disabled=true;status.textContent='Connecting…';try{const c=await matrixAPI('status');if(!c.configured){status.textContent='Run npm run setup:matrix, then npm run personal.';return}const data=await matrixAPI('accounts');matrixAccounts=data.items;status.innerHTML=matrixAccounts.map(a=>`<div class="matrix-account"><span>${esc(a.network)}</span><small>${esc(a.status.replaceAll('_',' '))}</small></div>`).join('')||'No accounts connected in Matrix'}catch(e){status.textContent=e.message}finally{if(button.isConnected)button.disabled=false}}
async function matrixChatPicker(){modal('Matrix chats',`<form id="matrix-chat-search"><select id="matrix-account" aria-label="Platform"><option value="">All connected accounts</option>${matrixAccounts.map(a=>`<option value="${esc(a.accountID)}">${esc(a.network)}</option>`).join('')}</select><div class="catalog-query"><input type="text" id="matrix-chat-query" placeholder="Chat name" aria-label="Find Matrix chat"><button class="btn" aria-label="Find chats">${icon('search')}</button></div></form><div id="matrix-chat-status" role="status"></div><div id="matrix-chat-results"></div><button class="btn full" id="matrix-more-chats" hidden>Load more</button>`);matrixSearchCursor=null;const lookup=async(more=false)=>{const status=document.querySelector('#matrix-chat-status'),results=document.querySelector('#matrix-chat-results'),params=new URLSearchParams({q:document.querySelector('#matrix-chat-query').value.trim(),account:document.querySelector('#matrix-account').value});if(more&&matrixSearchCursor)params.set('cursor',matrixSearchCursor);status.textContent='Loading chats…';if(!more)results.innerHTML='';try{const data=await matrixAPI('chats?'+params);if(!results.isConnected)return;matrixSearchCursor=data.cursor;status.textContent=data.items.length?'':'No chats';const fragment=document.createElement('div');fragment.innerHTML=data.items.map((chat,i)=>`<div class="matrix-chat-result"><span><strong>${esc(chat.title)}</strong><small>${esc(chat.network)}${chat.invited?' · Invitation':chat.type==='group'?' · Group':''}</small></span><button type="button" class="btn" data-import-chat="${i}">Add</button></div>`).join('');fragment.querySelectorAll('[data-import-chat]').forEach(button=>button.onclick=async()=>{const chat=data.items[+button.dataset.importChat];if(chat.invited){try{await matrixAPI('join',{method:'POST',body:JSON.stringify({room:chat.id})})}catch(e){status.textContent=e.message;return}}const id='matrix:'+encodeURIComponent(chat.id);let source=sources.find(s=>s.id===id);if(!source){source={id,name:chat.title,initial:chat.title.slice(0,1),color:'#aaa',type:chat.type==='group'?'Organization':'Person',bio:'',links:[chat.network],saved:true,matrixChatId:chat.id,matrixAccountID:chat.accountID,matrixNetwork:chat.network,matrixReadOnly:chat.isReadOnly};sources.push(source)}else source.saved=true;persist();document.querySelector('#modal').close();selectedSource=id;go('Source')});results.append(fragment);document.querySelector('#matrix-more-chats').hidden=!data.hasMore||!data.cursor}catch(e){if(status.isConnected)status.textContent=e.message}};document.querySelector('#matrix-chat-search').onsubmit=e=>{e.preventDefault();matrixSearchCursor=null;lookup()};document.querySelector('#matrix-more-chats').onclick=()=>lookup(true);document.querySelector('#matrix-chat-query').focus()}
function matrixChatState(id){if(!matrixChats.has(id))matrixChats.set(id,{messages:[],draft:'',loaded:false,loading:false,sending:false,cursor:null,hasMore:false,error:'',notice:''});return matrixChats.get(id)}
function matrixSourceView(source){const state=matrixChatState(source.id);return `<div class="page-title"><div><h1>${esc(source.name)}</h1><span class="matrix-network">${esc(source.matrixNetwork)}</span></div><button class="btn" data-tag-source="${source.id}" aria-label="Tags for ${esc(source.name)}">${icon('tag')}</button></div><section class="conversation matrix-conversation"><div class="matrix-chat-toolbar"><button class="text-action" id="refresh-matrix">${icon('refresh')} Refresh</button><button class="text-action" id="older-matrix" ${!state.hasMore?'hidden':''}>Earlier messages</button></div><div id="matrix-message-status" role="status"></div><div class="message-history" id="matrix-history" role="log" aria-live="polite"></div><form id="matrix-send-form"><textarea id="matrix-send-text" aria-label="Message ${esc(source.name)} on ${esc(source.matrixNetwork)}" placeholder="${source.matrixReadOnly?'Read-only chat':'Message '+esc(source.name)}" rows="1" ${source.matrixReadOnly||state.sending?'disabled':''}>${esc(state.draft)}</textarea><button class="composer-icon" aria-label="Send on ${esc(source.matrixNetwork)}" id="matrix-send-button" ${source.matrixReadOnly||state.sending?'disabled':''}>${icon('send')}</button></form></section>`}
function drawMatrixMessages(source){const root=document.querySelector('#matrix-history');if(!root||selectedSource!==source.id)return;const state=matrixChatState(source.id),wasBottom=root.scrollHeight-root.scrollTop-root.clientHeight<60,y=root.scrollTop;root.innerHTML=state.messages.map(m=>`<article class="chat-message"><span class="avatar">${esc((m.isSender?profile.name:m.senderName||source.name).slice(0,1))}</span><div class="message-main"><header><strong>${esc(m.isSender?profile.name:m.senderName||source.name)}</strong><time>${esc(m.timestamp?messageTime(m.timestamp,false):'')}</time></header>${m.text?`<p>${esc(m.text)}</p>`:''}${m.hasAttachments?`<div class="matrix-media">${m.image?`<img src="/api/matrix/media?${new URLSearchParams({room:source.matrixChatId,event:m.id})}" alt="${esc(m.fileName)}" loading="lazy">`:''}<a href="/api/matrix/media?${new URLSearchParams({room:source.matrixChatId,event:m.id})}" download>${esc(m.fileName||'Download attachment')}</a></div>`:''}${m.editedTimestamp?'<span class="edited-label">edited on platform</span>':''}</div></article>`).join('')+(state.loaded&&!state.messages.length?'<div class="empty">No messages</div>':'');root.scrollTop=wasBottom?root.scrollHeight:y;document.querySelector('#matrix-message-status').textContent=state.error||state.notice||(state.loading?'Loading…':'');document.querySelector('#older-matrix').hidden=!state.hasMore;const button=document.querySelector('#matrix-send-button');button.disabled=state.sending||source.matrixReadOnly||!document.querySelector('#matrix-send-text').value.trim();document.querySelector('#matrix-send-text').disabled=state.sending||source.matrixReadOnly}
async function loadMatrixMessages(source,older=false){const state=matrixChatState(source.id);if(state.loading)return;state.loading=true;state.error='';drawMatrixMessages(source);try{const params=new URLSearchParams({chat:source.matrixChatId});if(older&&state.cursor)params.set('cursor',state.cursor);const data=await matrixAPI('messages?'+params);const all=older?[...data.items,...state.messages]:data.items;state.messages=[...new Map(all.map(m=>[m.id,m])).values()].sort((a,b)=>new Date(a.timestamp)-new Date(b.timestamp));state.cursor=data.cursor;state.hasMore=data.hasMore;state.loaded=true}catch(e){state.error=e.message}finally{state.loading=false;drawMatrixMessages(source)}}
function bindMatrix(){document.querySelector('#check-matrix')?.addEventListener('click',checkMatrix);document.querySelector('#browse-matrix')?.addEventListener('click',matrixChatPicker);document.querySelector('#show-platforms')?.addEventListener('click',e=>{const list=document.querySelector('#messaging-platforms');list.hidden=!list.hidden;e.currentTarget.setAttribute('aria-expanded',String(!list.hidden));if(!list.hidden)loadMessagingPlatforms()});const source=sources.find(s=>s.id===selectedSource);if(!source?.matrixChatId||page!=='Source')return;const state=matrixChatState(source.id),input=document.querySelector('#matrix-send-text');document.querySelector('#refresh-matrix').onclick=()=>loadMatrixMessages(source);document.querySelector('#older-matrix').onclick=()=>loadMatrixMessages(source,true);input.oninput=()=>{state.draft=input.value;input.style.height='auto';input.style.height=Math.min(input.scrollHeight,180)+'px';drawMatrixMessages(source)};document.querySelector('#matrix-send-form').onsubmit=async e=>{e.preventDefault();if(state.sending||source.matrixReadOnly||!input.value.trim())return;const text=input.value;state.sending=true;state.error='';state.notice='Sending…';drawMatrixMessages(source);try{const data=await matrixAPI('messages?'+new URLSearchParams({chat:source.matrixChatId}),{method:'POST',body:JSON.stringify({text})});state.notice='Accepted by homeserver';if(input.value===text){input.value='';state.draft=''}await loadMatrixMessages(source)}catch(e){state.error=e.message;state.notice=''}finally{state.sending=false;drawMatrixMessages(source)}};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.querySelector('#matrix-send-form').requestSubmit()}};drawMatrixMessages(source);if(!state.loaded)loadMatrixMessages(source)}
icons.refresh='<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 4M18 18A8 8 0 0 1 5 14"/>';


async function loadMessagingPlatforms(){const target=document.querySelector('#messaging-platforms');if(!target)return;target.textContent='Loading platforms…';try{const data=await matrixAPI('bridges');if(!target.isConnected)return;target.innerHTML=data.items.map(b=>`<div class="platform-connection"><div><strong>${esc(b.name)}</strong><small>${b.status==='email'?(b.installed?'Account configured':'Not connected'):b.status==='native'?(b.installed?'Direct connection':'Setup required'):b.installed&&b.needsConfiguration?.length?'API credentials required':b.installed?(b.externalConfigured?'External bridge configured':b.status==='experimental'||b.community?'Community bridge installed':'Bridge installed'):b.status==='packaged'?'Setup required':b.status==='external'?b.id==='applemessages'?'Mac relay required':'Separate setup required':b.status==='experimental'?'Community bridge · Not verified':'Not available'}</small></div><div class="platform-actions">${b.status==='email'?`${b.installed?'<button class="text-action" data-email-open>Inbox</button>':''}<button class="btn" data-email-configure>${b.installed?'Configure':'Connect'}</button>`:b.status==='native'?`<button class="text-action" data-matrix-chats>Chats</button><button class="btn" data-matrix-new>New chat</button>`:b.installed&&b.needsConfiguration?.length?`<button class="btn" data-platform-credentials="${b.id}">Configure</button>`:b.installed?`<button class="text-action" data-platform-open="${b.id}">Open</button><button class="btn" data-platform-link="${b.id}">Link</button>`:b.status!=='unavailable'?`<button class="btn" data-platform-setup="${b.id}">Setup</button>`:''}</div></div>`).join('');target.querySelector('[data-email-open]')?.addEventListener('click',openEmailInbox);target.querySelector('[data-email-configure]')?.addEventListener('click',emailConfigure);target.querySelector('[data-matrix-chats]')?.addEventListener('click',matrixChatPicker);target.querySelector('[data-matrix-new]')?.addEventListener('click',newMatrixChat);target.querySelectorAll('[data-platform-credentials]').forEach(button=>button.onclick=telegramCredentials);target.querySelectorAll('[data-platform-link]').forEach(button=>button.onclick=()=>openPlatformBridge(button.dataset.platformLink,'link',button));target.querySelectorAll('[data-platform-open]').forEach(button=>button.onclick=()=>openPlatformBridge(button.dataset.platformOpen,'open',button));target.querySelectorAll('[data-platform-setup]').forEach(button=>button.onclick=()=>platformSetup(data.items.find(b=>b.id===button.dataset.platformSetup)))}catch(e){target.textContent=e.message}}
async function openPlatformBridge(id,action,button){if(button)button.disabled=true;const status=document.querySelector('#matrix-connection');if(status)status.textContent='Opening bridge…';try{const chat=await matrixAPI('bridges/'+id+'/'+action,{method:'POST',body:'{}'}),sourceId='matrix:'+encodeURIComponent(chat.id);let source=sources.find(s=>s.id===sourceId);if(!source){source={id:sourceId,name:chat.title,initial:chat.network.slice(0,1),color:'#aaa',type:'Person',bio:'',links:[chat.network],saved:true,matrixChatId:chat.id,matrixAccountID:'matrix',matrixNetwork:chat.network,matrixReadOnly:false};sources.push(source)}else source.saved=true;persist();selectedSource=sourceId;go('Source')}catch(e){if(status?.isConnected)status.textContent=e.message;if(button?.isConnected)button.disabled=false}}
function platformSetup(bridge){modal(esc(bridge.name),`${bridge.reason?`<p class="modal-intro">${esc(bridge.reason)}</p>`:''}${bridge.setupCommand?`<pre class="bridge-command">${esc(bridge.setupCommand)}</pre><p class="bridge-platform-note">Run on Windows, Linux, or macOS with Docker.</p>`:`<a class="text-action" href="${esc(bridge.url||'https://github.com/'+bridge.repo)}" target="_blank" rel="noreferrer">Upstream setup ${icon('out')}</a><p class="bridge-platform-note">After registering the bridge on your homeserver, add its bot below.</p><form id="external-bridge-form"><label class="category-field">Matrix bot ID<input type="text" id="external-bot" required placeholder="@bridgebot:nav.local" value="${bridge.bot?'@'+bridge.bot+':nav.local':''}"></label><label class="category-field">Command prefix<input type="text" id="external-prefix" required value="${esc(bridge.prefix||'!bridge')}"></label><button class="btn full">Save external bridge</button></form><div id="external-bridge-status" role="status"></div>`}`);document.querySelector('#external-bridge-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await matrixAPI('bridges/'+bridge.id+'/configure',{method:'POST',body:JSON.stringify({bot:document.querySelector('#external-bot').value.trim(),prefix:document.querySelector('#external-prefix').value.trim()})});document.querySelector('#modal').close();loadMessagingPlatforms()}catch(error){document.querySelector('#external-bridge-status').textContent=error.message}})}

function telegramCredentials(){modal('Telegram API credentials',`<p class="bridge-platform-note">Create your API ID and hash at <a href="https://my.telegram.org/apps" target="_blank" rel="noreferrer">my.telegram.org/apps</a>.</p><form id="telegram-credentials"><label class="category-field">API ID<input type="number" id="telegram-api-id" required min="1" autocomplete="off"></label><label class="category-field">API hash<input type="password" id="telegram-api-hash" required autocomplete="off"></label><button class="btn full">Save locally</button></form><div id="telegram-credentials-status" role="status"></div>`);document.querySelector('#telegram-credentials').onsubmit=async e=>{e.preventDefault();try{await matrixAPI('bridges/telegram/credentials',{method:'POST',body:JSON.stringify({apiID:document.querySelector('#telegram-api-id').value,apiHash:document.querySelector('#telegram-api-hash').value})});document.querySelector('#telegram-api-hash').value='';document.querySelector('#telegram-credentials-status').textContent='Saved. Run npm run setup:bridges -- telegram, then reopen Platforms.'}catch(error){document.querySelector('#telegram-credentials-status').textContent=error.message}}}
document.addEventListener('keydown' ,e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();go('Search');document.querySelector('#search-input').focus()}});publishDuePosts();render();

function newMatrixChat(){modal('Matrix',`<form id="matrix-new-chat"><label class="category-field">User or room<input type="text" id="matrix-target" placeholder="@user:server or #room:server" autocomplete="off" required></label><button class="btn full">Open chat</button></form><div id="matrix-new-status" role="status"></div>`);document.querySelector('#matrix-target').focus();document.querySelector('#matrix-new-chat').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button'),status=document.querySelector('#matrix-new-status');button.disabled=true;status.textContent='Opening…';try{const chat=await matrixAPI('conversations',{method:'POST',body:JSON.stringify({target:document.querySelector('#matrix-target').value.trim()})}),id='matrix:'+encodeURIComponent(chat.id);let source=sources.find(s=>s.id===id);if(!source){source={id,name:chat.title,initial:chat.title.slice(0,1),color:'#aaa',type:chat.type==='group'?'Organization':'Person',bio:'',links:['Matrix'],saved:true,matrixChatId:chat.id,matrixAccountID:'matrix',matrixNetwork:'Matrix',matrixReadOnly:false};sources.push(source)}else source.saved=true;persist();document.querySelector('#modal').close();selectedSource=id;go('Source');if(chat.warning)toast(chat.warning)}catch(error){if(status.isConnected)status.textContent=error.message}finally{if(button.isConnected)button.disabled=false}}}

async function emailAPI(route,options={}){const account=page==='Source'?sources.find(s=>s.id===selectedSource)?.emailAccount:null;const response=await fetch('/api/email/'+route,{...options,headers:{...(account?{'X-Email-Account':account}:{}),...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Email request failed');return data}
async function emailConfigure(){let account;try{account=await emailAPI('status')}catch(e){toast(e.message);return}modal('Email',`<form id="email-connect"><label class="category-field">Email address<input type="email" id="email-address" required value="${esc(account.address||'')}" autocomplete="username"></label><label class="category-field">Username<input id="email-username" value="${esc(account.username||'')}" autocomplete="off" placeholder="Same as email address"></label><label class="category-field">App password<input type="password" id="email-password" autocomplete="new-password" ${account.configured?'':'required'} placeholder="${account.configured?'Leave empty to keep current password':''}"></label>${['imap','smtp'].map(kind=>`<fieldset class="email-server"><legend>${kind.toUpperCase()}</legend><label class="category-field">Server<input id="email-${kind}-host" required value="${esc(account[kind]?.host||'')}"></label><label class="category-field">Port<input id="email-${kind}-port" type="number" min="1" max="65535" required value="${account[kind]?.port||(kind==='imap'?993:465)}"></label><label class="category-field">Encryption<select id="email-${kind}-tls"><option value="tls" ${account[kind]?.secure!==false?'selected':''}>TLS</option><option value="starttls" ${account[kind]?.secure===false?'selected':''}>STARTTLS</option></select></label></fieldset>`).join('')}<div class="email-actions">${account.configured?'<button type="button" class="text-action" id="email-disconnect">Disconnect</button>':''}<button class="btn" id="email-connect-submit">Connect</button></div></form><div id="email-connect-status" role="status"></div>`);document.querySelector('#email-connect').onsubmit=async e=>{e.preventDefault();const button=document.querySelector('#email-connect-submit'),status=document.querySelector('#email-connect-status');button.disabled=true;status.textContent='Connecting…';const data={address:document.querySelector('#email-address').value.trim(),username:document.querySelector('#email-username').value.trim(),password:document.querySelector('#email-password').value};for(const kind of ['imap','smtp'])data[kind]={host:document.querySelector('#email-'+kind+'-host').value.trim(),port:Number(document.querySelector('#email-'+kind+'-port').value),secure:document.querySelector('#email-'+kind+'-tls').value==='tls'};try{await emailAPI('configure',{method:'POST',body:JSON.stringify(data)});document.querySelector('#email-password').value='';emailState.items=[];emailState.message=null;emailState.address='';document.querySelector('#modal').close();loadMessagingPlatforms()}catch(error){if(status.isConnected)status.textContent=error.message}finally{if(button.isConnected)button.disabled=false}};document.querySelector('#email-disconnect')?.addEventListener('click',async()=>{try{await emailAPI('disconnect',{method:'POST',body:'{}'});emailState.items=[];emailState.message=null;emailState.address='';document.querySelector('#modal').close();loadMessagingPlatforms()}catch(e){document.querySelector('#email-connect-status').textContent=e.message}})}
async function openEmailInbox(){try{const account=await emailAPI('status');if(!account.configured){emailConfigure();return}const id='email:'+account.address;let source=sources.find(s=>s.id===id);if(!source){source={id,name:account.address,initial:'@',color:'#aaa',type:'Person',bio:'',links:['Email'],saved:true,emailAccount:account.address};sources.push(source)}else source.saved=true;if(emailState.address!==account.address){emailState.items=[];emailState.message=null;emailState.hasMore=false;emailState.before=null}emailState.address=account.address;persist();selectedSource=id;go('Source');loadEmailInbox()}catch(e){toast(e.message)}}
function emailSourceView(source){if(emailState.address!==source.emailAccount){emailState.items=[];emailState.message=null;emailState.hasMore=false;emailState.before=null;emailState.address=source.emailAccount}return `<div class="page-title"><h1>${esc(source.name)}</h1></div><div class="email-actions"><button class="text-action" id="email-refresh">Refresh</button><button class="btn" id="email-compose">New email</button></div><div id="email-status" role="status"></div><div id="email-inbox"></div><button class="text-action" id="email-more" ${emailState.hasMore?'':'hidden'}>Earlier messages</button><article id="email-message"></article>`}
function bindEmail(){const source=sources.find(s=>s.id===selectedSource);if(page!=='Source'||!source?.emailAccount)return;document.querySelector('#email-refresh').onclick=()=>loadEmailInbox();document.querySelector('#email-compose').onclick=()=>emailCompose();document.querySelector('#email-more').onclick=()=>loadEmailInbox(true);drawEmailInbox();if(emailState.message)drawEmailMessage(emailState.message)}
function emailAddresses(values){return (values||[]).map(a=>a.name?`${a.name} <${a.address}>`:a.address).join(', ')}
function drawEmailInbox(){const root=document.querySelector('#email-inbox');if(!root)return;root.innerHTML=emailState.items.map(m=>`<button class="email-row ${m.read?'':'unread'}" data-email-message="${m.uid}"><span>${esc(emailAddresses(m.from))}</span><strong>${esc(m.subject)}</strong><time>${esc(m.date?messageTime(m.date):'')}</time></button>`).join('');root.querySelectorAll('[data-email-message]').forEach(b=>b.onclick=()=>openEmailMessage(Number(b.dataset.emailMessage)));const more=document.querySelector('#email-more');if(more)more.hidden=!emailState.hasMore}
async function loadEmailInbox(older=false){const status=document.querySelector('#email-status');if(!status)return;status.textContent='Loading…';try{const account=await emailAPI('status');if(!account.configured||account.address!==sources.find(s=>s.id===selectedSource)?.emailAccount)throw Error('This email account is disconnected');const data=await emailAPI('inbox'+(older?'?before='+emailState.before:''));if(!status.isConnected)return;emailState.items=older?[...emailState.items,...data.items]:data.items;emailState.before=data.before;emailState.hasMore=data.hasMore;status.textContent=emailState.items.length?'':'No messages';drawEmailInbox()}catch(e){if(status.isConnected)status.textContent=e.message}}
async function openEmailMessage(uid){const status=document.querySelector('#email-status');status.textContent='Loading…';try{const message=await emailAPI('message?uid='+uid);if(!status.isConnected)return;emailState.message=message;status.textContent='';drawEmailMessage(message)}catch(e){if(status.isConnected)status.textContent=e.message}}
function drawEmailMessage(message){const root=document.querySelector('#email-message');if(!root)return;root.innerHTML=`<header><h2>${esc(message.subject)}</h2><p>${esc(emailAddresses(message.from))}</p><p>${esc(emailAddresses(message.to))}</p><div class="email-actions"><button class="btn" id="email-reply">Reply</button><button class="text-action" id="email-mark-read">Mark read</button><button class="text-action" id="email-close-message">Close</button></div></header><div class="email-body">${esc(message.text)}</div><div class="email-attachments">${message.attachments.map(a=>`<a href="/api/email/attachment?uid=${message.uid}&index=${a.index}&account=${encodeURIComponent(emailState.address)}" download>${icon('folder')} ${esc(a.filename)}</a>`).join('')}</div>`;document.querySelector('#email-reply').onclick=()=>emailCompose(message);document.querySelector('#email-close-message').onclick=()=>{emailState.message=null;root.innerHTML=''};document.querySelector('#email-mark-read').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{await emailAPI('read',{method:'POST',body:JSON.stringify({uid:message.uid})});const item=emailState.items.find(m=>m.uid===message.uid);if(item)item.read=true;drawEmailInbox()}catch(error){toast(error.message);if(button.isConnected)button.disabled=false}}}
function emailCompose(reply){const draft={to:reply?(reply.replyTo||[]).map(a=>a.address).join(', '):'',cc:'',bcc:'',subject:reply?(/^re:/i.test(reply.subject)?reply.subject:'Re: '+reply.subject):'',text:'',files:[]};modal(reply?'Reply':'New email',`<form id="email-send-form"><label class="category-field">To<input id="email-to" required value="${esc(draft.to)}"></label><details class="email-copy"><summary>Cc / Bcc</summary><label class="category-field">Cc<input id="email-cc"></label><label class="category-field">Bcc<input id="email-bcc"></label></details><label class="category-field">Subject<input id="email-subject" value="${esc(draft.subject)}"></label><textarea id="email-text" aria-label="Email message" rows="8"></textarea><input type="file" id="email-files" multiple hidden><div id="email-file-list"></div><div class="email-actions"><button type="button" class="text-action" id="email-add-files">${icon('plus')} Files</button><button class="btn" id="email-send">Send</button></div></form><div id="email-send-status" role="status"></div>`);document.querySelector('#email-add-files').onclick=()=>document.querySelector('#email-files').click();document.querySelector('#email-files').onchange=e=>{draft.files.push(...e.target.files);e.target.value='';drawFiles()};function drawFiles(){const list=document.querySelector('#email-file-list');list.innerHTML=draft.files.map((f,i)=>`<div>${esc(f.name)}<button type="button" data-remove-email-file="${i}" aria-label="Remove ${esc(f.name)}">${icon('close')}</button></div>`).join('');list.querySelectorAll('[data-remove-email-file]').forEach(b=>b.onclick=()=>{draft.files.splice(Number(b.dataset.removeEmailFile),1);drawFiles()})}document.querySelector('#email-send-form').onsubmit=async e=>{e.preventDefault();const button=document.querySelector('#email-send'),status=document.querySelector('#email-send-status');button.disabled=true;status.textContent='Sending…';try{const attachments=[];for(const file of draft.files){const contentBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read '+file.name));reader.readAsDataURL(file)});attachments.push({filename:file.name,contentType:file.type,contentBase64})}const data={to:document.querySelector('#email-to').value,cc:document.querySelector('#email-cc').value,bcc:document.querySelector('#email-bcc').value,subject:document.querySelector('#email-subject').value,text:document.querySelector('#email-text').value,attachments,...(reply?{replyUid:reply.uid}:{})};const result=await emailAPI('send',{method:'POST',body:JSON.stringify(data)});if(result.rejected.length){status.textContent='SMTP accepted: '+result.accepted.join(', ')+'. Rejected: '+result.rejected.join(', ')+'. Check before retrying.';return}document.querySelector('#modal').close();toast('Accepted by SMTP server')}catch(error){if(status.isConnected)status.textContent=error.message}finally{if(button.isConnected)button.disabled=false}}}

// Keep secondary actions and navigation predictable across mouse, touch and keyboard.
function savedHeading(){return `<div class="page-title saved-heading"><h1 class="sr-only">Saved</h1><div class="saved-view-switch" role="group" aria-label="Saved content"><button id="saved-media" aria-pressed="${savedViewType==='media'}">All</button><button id="saved-posts" aria-pressed="${savedViewType==='posts'}">Posts</button></div>${savedViewType==='media'?'<div id="saved-heading-actions"></div>':''}</div>`}
function setNavigation(open){const sidebar=document.querySelector('.sidebar'),trigger=document.querySelector('#mobile-menu');if(!sidebar||!trigger)return;sidebar.classList.toggle('open',open);trigger.setAttribute('aria-expanded',String(open));document.querySelector('#navigation-scrim').hidden=!open;document.querySelector('.main').inert=open;const dock=document.querySelector('#media-dock');if(dock)dock.inert=open;if(open)document.querySelector('#close-navigation').focus();else trigger.focus()}
function bindInterface(){const trigger=document.querySelector('#mobile-menu');trigger.onclick=()=>setNavigation(!document.querySelector('.sidebar').classList.contains('open'));document.querySelector('#close-navigation').onclick=()=>setNavigation(false);document.querySelector('#navigation-scrim').onclick=()=>setNavigation(false);const dock=document.querySelector('#media-dock');if(dock)dock.inert=false;document.querySelectorAll('.source-row-menu').forEach(menu=>{menu.addEventListener('toggle',()=>{if(menu.open){document.querySelectorAll('.source-row-menu[open]').forEach(other=>{if(other!==menu)other.open=false});positionSourceMenu(menu)}});menu.addEventListener('click',event=>{if(event.target.closest('button')){menu.open=false;const dialog=document.querySelector('#modal');if(dialog.open)dialog.addEventListener('close',()=>{if(menu.isConnected)menu.querySelector('summary').focus()},{once:true})}})})}
document.addEventListener('click',event=>{document.querySelectorAll('.source-row-menu[open]').forEach(menu=>{if(!menu.contains(event.target))menu.open=false})});
document.addEventListener('keydown',event=>{const nav=document.querySelector('.sidebar.open');if(event.key==='Escape'&&!document.querySelector('#modal')?.open){if(nav){event.preventDefault();setNavigation(false)}document.querySelectorAll('.source-row-menu[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary').focus()})}if(nav&&event.key==='Tab'&&!document.querySelector('#modal')?.open){const focusable=[...nav.querySelectorAll('button:not(:disabled),a[href],input,select,[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&!event.altKey&&!document.querySelector('#modal')?.open){event.preventDefault();if(nav)setNavigation(false);const search=document.querySelector('#search-input');search?.focus();search?.select()}});
window.matchMedia('(max-width:700px)').addEventListener('change',event=>{if(!event.matches&&document.querySelector('.sidebar.open'))setNavigation(false)});

document.querySelector('#app').addEventListener('scroll',()=>document.querySelectorAll('.source-row-menu[open]').forEach(positionSourceMenu),{passive:true});

function positionSourceMenu(menu){const panel=menu.querySelector('.source-menu-actions'),anchor=menu.querySelector('summary').getBoundingClientRect(),viewport=document.querySelector('#app').getBoundingClientRect(),bottom=Math.min(innerHeight,viewport.bottom);if(anchor.bottom<viewport.top||anchor.top>bottom){menu.open=false;return}panel.style.maxHeight=Math.max(80,bottom-32)+'px';panel.style.left=Math.max(16,Math.min(innerWidth-panel.offsetWidth-16,anchor.right-panel.offsetWidth))+'px';panel.style.top=Math.max(16,Math.min(bottom-panel.offsetHeight-16,anchor.bottom+8))+'px'}
window.addEventListener('resize',()=>document.querySelectorAll('.source-row-menu[open]').forEach(positionSourceMenu));
